// Єзекиїля — Біблія, переклад Патріарха Філарета. Згенеровано scripts/build_bible.py, не правте вручну.
import type { BChap } from '../types';
const C: BChap[] = [{"v":["І було у тридцятий рік, у четвертий місяць, у п’ятий день місяця, коли я знаходився серед переселенців біля річки Ховарі, розверзлися небеса, і я бачив видіння Боже.","У п’ятий день місяця (це був п’ятий рік від полонення царя Іоакима),","було слово Господнє до Єзекиїля, сина Вузія, священика, у землі Халдейській, біля річки Ховарі; і була на ньому там рука Господня.","І я бачив, і ось, бурхливий вітер ішов від півночі, велика хмара і вогонь, що клубочився, і сяйво навколо нього,","а із середини його ніби світло полум’я із середини вогню; і з середини його видно було подобу чотирьох тварин, — і такий був вигляд їх: вигляд їх був, як у людини;","і в кожної чотири лиця, і в кожної з них чотири крила;","а ноги їх — ноги прямі, і ступні ніг їх — як ступня ноги у тельця, і блищали, як блискуча мідь, (і крила їх легкі).","І руки людські були під крилами їх, на чотирьох боках їх;","і лиця у них і крила у них — у всіх чотирьох; крила їх торкалися одне одного; під час ходи своєї вони не поверталися, а йшли кожне в напрямку лиця свого.","Подоба лиць їх — лице людини й лице лева з правого боку у всіх їх чотирьох; а з лівого боку лице тельця у всіх чотирьох і лице орла у всіх чотирьох.","І лиця їх і крила їх зверху були розділені, але у кожного два крила торкалися одне одного, а два покривали тіла їх.","І йшли вони, кожне у той бік, який перед лицем його; куди дух хотів іти, туди і йшли; під час ходи своєї не поверталися.","І вигляд цих тварин був як вигляд палаючих вуглин, як вигляд лампад; вогонь ходив між тваринами, і сяйво від вогню і блискавка виходила з вогню.","І тварини швидко рухалися туди і сюди, як блискає блискавка.","І я дивився на тварин, і ось, на землі біля цих тварин по одному колесу перед чотирма лицями їх.","Вигляд коліс і побудова їх — як вигляд топаза, і подоба у всіх чотирьох одна; і за виглядом їх і за побудовою їх здавалося, ніби колесо знаходилося у колесі.","Коли вони йшли, йшли на чотири свої боки; під час ходи не поверталися.","А ободи їх — високі і страшні були вони; ободи їх у всіх чотирьох навколо повні були очей.","І коли йшли тварини, йшли і колеса поряд з ними; а коли тварини піднімалися від землі, тоді піднімалися і колеса.","Куди дух хотів іти, туди йшли і вони; куди б не пішов дух, і колеса піднімалися нарівні з ними, бо дух тварин був у колесах.","Коли йшли ті, йшли і вони; і коли ті стояли, стояли і вони; і коли ті піднімалися від землі, тоді нарівні з ними піднімалися і колеса, тому що дух тварин був у колесах.","Над головами тварин була подоба склепіння, як вигляд дивного кристала, простертого згори над головами їх.","А під склепінням простягалися крила їх прямо одне до іншого, й у кожного було два крила, які покривали їх, у кожного два крила покривали тіла їх.","І коли вони йшли, я чув шум крил їх, ніби шум великих вод, ніби глас Всемогутнього, сильний шум, ніби шум у військовому стані; а коли вони зупинялися, опускали крила свої.","І голос був зі склепіння, яке над головами їх; коли вони зупинялися, тоді опускали крила свої.","А над склепінням, яке над головами їх, була подоба престолу на вигляд ніби із каменя сапфіра; а над подобою престолу була ніби подоба людини вгорі на ньому.","І бачив я ніби палаючий метал, ніби вигляд вогню всередині нього навколо; від вигляду стегон його і вище і від вигляду стегон його і нижче я бачив ніби якийсь вогонь, і сяйво було навколо нього.","В якому вигляді буває веселка на хмарах під час дощу, такий вигляд мало це сяйво навколо."],"x":{"1":"25.136.1","2":"11.24.1","3":"36.3.23|36.43.3","4":"24.38.1","6":"36.10.14","10":"36.41.19|76.4.7","14":"36.10.20","15":"36.10.9:12","16":"36.10.9","18":"76.4.6","20":"36.10.17","24":"36.43.2","26":"36.10.1","27":"36.8.2","28":"30.43.12"}},{"v":["Таке було видіння подоби слави Господньої. Побачивши це, я упав на лице своє, і чув глас Того, Хто говорив, і Він сказав мені: сину людський! стань на ноги твої, і Я буду говорити з тобою.","І коли Він говорив мені, ввійшов у мене дух і поставив мене на ноги мої, і я чув Того, Хто говорив мені.","І Він сказав мені: сину людський! Я посилаю тебе до синів Ізраїлевих, до людей непокірливих, які збурилися проти Мене; вони і батьки їхні зрадники переді Мною до цього самого дня.","І ці сини з огрубілим лицем і з жорстоким серцем; до них Я посилаю тебе, і ти скажеш їм: «так говорить Господь Бог!»","Чи будуть вони слухати, чи не будуть, бо вони бунтівний дім; але нехай знають, що був пророк серед них.","А ти, сину людський, не бійся їх і не бійся слів їхніх, якщо вони бур’яном і терням будуть для тебе, і ти будеш жити у скорпіонів; не бійся слів їхніх і не страшися лиця їх, бо вони бунтівний дім;","і говори їм слова Мої, чи будуть вони слухати, чи не будуть, бо вони вперті.","Ти ж, сину людський, слухай, що Я буду говорити тобі; не будь упертим, як цей бунтівний дім; відкрий уста твої і з’їж, що Я дам тобі.","І побачив я, і ось, рука простягнена до мене, і ось, у ній книжковий сувій.","І Він розгорнув його переді мною, і ось, сувій списаний був усередині і ззовні, і написано на ньому: «плач, і стогін, і горе»."],"x":{"1":"54.7.55|76.21.11|37.8.17","3":"25.77.8|32.3.25|32.7.26","4":"31.48.4|32.5.3|51.10.5","5":"36.3.11|36.12.2|31.30.9","6":"32.1.8|43.7.2","8":"76.10.9","9":"32.1.9|76.5.1"}},{"v":["І сказав мені: сину людський! з’їж, що перед тобою, з’їж цей сувій, і йди, говори дому Ізраїлевому.","Тоді я відкрив уста мої, і Він дав мені з’їсти цей сувій;","і сказав мені: сину людський! насить утробу твою і наповни нутрощі твої цим сувоєм, який Я даю тобі; і я з’їв, і було у вустах моїх солодко, як мед.","І Він сказав мені: сину людський! встань і йди до дому Ізраїлевого, і говори їм Моїми словами;","бо не до народу зі словами нерозбірливими і з незрозумілою мовою ти посилаєшся, але до дому Ізраїлевого,","не до народів багатьох з нерозбірливими словами і зі незрозумілою мовою, яких слів ти не розумів би; та якби Я послав тебе і до них, то вони послухали б тебе;","а дім Ізраїлів не захоче слухати тебе; бо вони не хочуть слухати Мене, тому що весь дім Ізраїлів з твердим лобом і жорстоким серцем.","Ось, Я зробив і твоє лице міцним проти лиць їх, і твоє чоло твердим проти їх лоба.","Як алмаз, який міцніший за камінь, зробив Я чоло твоє; не бійся їх і не страшися перед лицем їх, бо вони бунтівний дім.","І сказав мені: сину людський! усі слова Мої, які буду говорити тобі, прийми серцем твоїм і вислухай вухами твоїми;","встань і піди до переселених, до синів народу твого, і говори до них, і скажи їм: «так говорить Господь Бог!» чи будуть вони слухати, чи не будуть.","І підняв мене дух; і я чув позаду себе великий громовий голос: «благословенна слава Господа від місця свого!»","і також шум крил тварин, що торкаються одне одного, і стукіт коліс поряд з ними, і звук сильного грому.","І дух підняв мене, і взяв мене. І йшов я засмученим, зі стривоженим духом; і рука Господня була міцно на мені.","І прийшов я до переселених у Тел-Авив, що живуть при ріці Ховарі, і зупинився там, де вони жили, і провів серед них сім днів у здивуванні.","Після семи ж днів було до мене слово Господнє:","сину людський! Я поставив тебе стражем дому Ізраїлевому, і ти будеш слухати слово з уст Моїх, і будеш напоумлювати їх від Мене.","Коли Я скажу беззаконникові: «смертю помреш!», а ти не будеш напоумлювати його і говорити, щоб застерегти беззаконника від беззаконного путі його, щоб він живим був, то беззаконник той помре у беззаконні своєму, і Я стягну кров його від рук твоїх.","Але якщо ти напоумлював беззаконника, а він не навернувся від беззаконня свого і від беззаконного путі свого, то він помре у беззаконні своєму, а ти спас душу твою.","І якщо праведник відступить від правди своєї і вчинить беззаконно, коли Я покладу перед ним перешкоду, і він помре, то, якщо ти не напоумлював його, він помре за гріх свій, і не згадаються йому праведні діла його, які робив він; і Я стягну кров його від рук твоїх.","Якщо ж ти будеш напоумлювати праведника, щоб праведник не згрішив, і він не згрішить, то і він живий буде, тому що був напоумленим, і ти спас душу твою.","І була на мені там рука Господа, і Він сказав мені: встань і вийди у поле, і Я буду говорити там з тобою.","І встав я, і вийшов у поле; і ось, там стояла слава Господня, як слава, яку бачив я біля ріки Ховарі; й упав я на лице своє.","І ввійшов у мене дух, і поставив мене на ноги мої, і Він говорив зі мною, і сказав мені: йди і замкнися у домі твоєму.","І ти, сину людський, — ось, покладуть на тебе пута, і зв’яжуть тебе ними, і не будеш ходити серед них.","І язик твій Я приліплю до гортані твоєї, і ти онімієш, і не будеш викривачем їх, бо вони бунтівний дім.","А коли Я буду говорити з тобою, тоді відкрию вуста твої, і ти будеш говорити їм: «так говорить Господь Бог!» хто хоче слухати, слухай; а хто не хоче слухати, не слухай: бо вони бунтівний дім."],"x":{"1":"76.10.9","3":"76.10.10","5":"31.33.19","7":"31.48.4","8":"32.1.18","9":"32.1.8","11":"36.2.5","12":"36.8.3","17":"36.33.7","18":"57.1.13|36.34.10|71.5.22","19":"54.18.6|54.20.26","20":"36.18.24","23":"36.1.3|36.8.4","24":"36.2.2","25":"36.4.8","26":"36.12.2","27":"36.2.5|76.22.11"}},{"v":["І ти, сину людський, візьми собі цеглу і поклади її перед собою, і накресли на ній місто Єрусалим;","і влаштуй облогу проти нього, і зроби укріплення проти нього, і насип вал навколо нього, і розташуй стан навпроти нього, і розстав навколо проти нього стінопробивні машини;","і візьми собі залізну дошку, і постав її ніби залізну стіну між тобою і містом, і зверни на нього лице твоє, і воно буде в облозі, і ти облягай його. Це буде знаменням дому Ізраїлевому.","Ти ж лягай на лівий бік твій і поклади на нього беззаконня дому Ізраїлевого: за числом днів, у які будеш лежати на ньому, ти будеш нести беззаконня їх.","І Я визначив тобі роки беззаконня їх числом днів: триста дев’яносто днів ти будеш нести беззаконня дому Ізраїлевого.","І коли виконаєш це, то вдруге лягай уже на правий бік, і сорок днів неси на собі беззаконня дому Іудиного, день за рік, день за рік Я визначив тобі.","І поверни лице твоє й оголену праву руку твою на облогу Єрусалима, і пророкуй проти нього.","Ось, Я поклав на тебе кайдани, і ти не повернешся з одного боку на другий, доки не виконаєш днів облоги твоєї.","Візьми собі пшениці і ячменю, і бобів, і сочевиці, і пшона, і полби, і всип їх в одну посудину, і зроби собі з них хліби, за числом днів, у які ти будеш лежати на боці твоєму; триста дев’яносто днів ти будеш їсти їх.","І їжу твою, якою будеш годуватися, їж вагою по двадцять сиклів на день; від часу до часу їж це.","І воду пий мірою, по шостій частині гина пий; від часу до часу пий так.","І їж, як ячмінні коржі, і печи їх на очах їх на людському калі.","І сказав Господь: так сини Ізраїлеві будуть їсти нечистий хліб свій серед тих народів, до яких Я вижену їх.","Тоді сказав я: о, Господи Боже! душа моя ніколи не осквернялася, і мертвечини і роздертого звіром я не їв від юности моєї донині; і ніяке нечисте м’ясо не входило у вуста мої.","І сказав Він мені: ось, Я дозволяю тобі, замість людського калу, коров’ячий кізяк, і на ньому готуй хліб твій.","І сказав мені: сину людський! ось, Я розтрощу у Єрусалимі опору хлібну, і будуть їсти хліб за вагою і в печалі, і воду будуть пити мірою й у смутку,","тому що у них буде нестача у хлібі й воді; і вони з жахом будуть дивитися один на одного, і зачахнуть у беззаконні своєму."],"x":{"2":"36.17.17","6":"3.14.34","8":"36.3.25","13":"38.9.3","14":"2.22.8","16":"2.26.26|36.5.16|36.12.19|36.14.13","17":"33.2.12|36.24.22-23"}},{"v":["А ти, сину людський, візьми собі гострий ніж, бритву цирульників візьми собі, і води нею по голові твоїй і по бороді твоїй, і візьми собі терези, і розділи волосся на частини.","Третину спали вогнем посередині міста, коли сповняться дні облоги; третину візьми і порубай ножем на околицях його; і третину розвій по вітру; а Я оголю меч слідом за ними.","І візьми з цього невелику кількість, і зав’яжи їх у себе у поли.","Але й із цього ще візьми, і кинь у вогонь, і спали це у вогні. Звідти вийде вогонь на весь дім Ізраїлів.","Так говорить Господь Бог: це Єрусалим! Я поставив його серед народів, і навколо нього — зе́млі.","А він учинив проти постанов Моїх нечестивіше за язичників, і проти уставів Моїх — гірше, ніж зе́млі навколо нього; бо вони відкинули постанови Мої і за уставами Моїми не чинять.","Тому так говорить Господь Бог: за те, що ви примножили беззаконня ваші більше, ніж язичники, які навколо вас, за уставами Моїми не чините і постанов Моїх не виконуєте, і навіть не чините і за постановами язичників, які навколо вас, —","тому так говорить Господь Бог: ось і Я проти тебе, Я Сам, і вчиню проти тебе суд, перед очима язичників.","І зроблю над тобою те, чого Я ніколи не робив і до чого подібного надалі не буду робити, за всі твої мерзоти.","За те батьки будуть їсти синів серед тебе, і сини будуть їсти батьків своїх; і вчиню над тобою суд, і весь залишок твій розвію по усіх вітрах.","Тому, — живу Я, — говорить Господь Бог, — за те, що ти осквернив святилище Моє всіма мерзотами твоїми і всіма гидотами твоїми, Я принижу тебе, і не пошкодує око Моє, і Я не помилую тебе.","Третина у тебе помре від моровиці і загине від голоду серед тебе; третина впаде від меча на околицях твоїх; а третину розвію по усіх вітрах, і оголю меч слідом за ними.","І звершиться гнів Мій, і вгамую лють Мою над ними, і задовольнюся; і пізнають, що Я, Господь, говорив у ревності Моїй, коли звершиться над ними лють Моя.","І зроблю тебе пустелею і наругою серед народів, які навколо тебе, перед очима кожного, хто проходить.","І будеш посміянням і наругою, прикладом і жахом у народів, які навколо тебе, коли Я вчиню над тобою суд у гніві й люті, і у лютих карах; — Я, Господь, прорік це; —","і коли пошлю на них люті стріли голоду, які будуть губити, коли пошлю їх на загибель вашу, і посилю голод між вами, і знищу хлібну опору у вас,","і пошлю на вас голод і лютих звірів, і будете ви бездітними; і виразка і кров пройде по тобі, і меч наведу на тебе; Я, Господь, вирік це."],"x":{"3":"36.12.14","6":"31.2.6|32.2.11|36.11.12","7":"36.11.12","8":"32.1.16|32.7.14|36.5.14","10":"4.28.53|11.6.29|33.4.10","11":"36.7.4","12":"36.12.14","13":"36.7.8","14":"33.2.15|33.5.1","15":"4.28.37|36.14.8","16":"36.4.16|36.14.13","17":"2.26.22|36.21.17"}},{"v":["І було до мене слово Господнє:","сину людський! поверни лице твоє до гір Ізраїлевих і проречи на них,","і скажи: гори Ізраїлеві! слухайте слово Господа Бога. Так говорить Господь Бог горам і пагорбам, долинам і лощинам: ось, Я наведу на вас меч, і зруйную висоти ваші;","і жертовники ваші будуть спустошені, стовпи ваші на честь сонця будуть розбиті, і повалю убитих ваших перед ідолами вашими;","і покладу трупи синів Ізраїлевих перед ідолами їхніми, і розсиплю кістки ваші навколо жертовників ваших.","У всіх місцях вашого мешкання міста́ будуть спустошені й висоти зруйновані, для того, щоб спустошені і зруйновані були жертовники ваші, щоб розтрощені і знищені були ідоли ваші, й розбиті сонячні стовпи ваші, і згладилися витвори ваші.","Й будуть падати серед вас убиті, і пізнаєте, що Я Господь.","Але Я збережу залишок, так що будуть у вас серед народів такі, які вціліли від меча, коли ви будете розсіяні по землях.","І згадають про Мене вцілілі ваші серед народів, куди будуть відведені у полон, коли Я скрушу блудне серце їх, що відпало від Мене, і очі їхні, що блудили вслід ідолам; і вони до самих себе відчують огиду за те зло, яке вони робили в усіх мерзотах своїх;","і пізнають, що Я Господь; не даремно говорив Я, що наведу на них таку біду.","Так говорить Господь Бог: сплесни руками твоїми і тупни ногою твоєю, і скажи: горе за всі мерзенні злодіяння дому Ізраїлевого! упадуть вони від меча, голоду і моровиці.","Хто далеко, той помре від моровиці; а хто близько, той упаде від меча; а хто залишився й уцілів, помре від голоду; так звершу над ними гнів Мій.","І пізнаєте, що Я Господь, коли уражені будуть лежати між ідолами своїми навколо жертовників їх, на всякому високому пагорбі, на всіх вершинах гір і під усяким зеленим деревом, і під усяким гіллястим дубом, на тому місці, де вони приносили запашні куріння всім ідолам своїм.","І простягну на них руку Мою, і зроблю землю пустелею і степом, від пустелі Дивлаф, у всіх місцях проживання їх, і пізнають, що Я Господь."],"x":{"2":"36.36.1","3":"36.36.2|40.4.1","4":"2.26.30","7":"36.7.27","8":"31.43.5|36.12.16","9":"31.45.17|36.20.43|36.36.31","11":"36.21.12","12":"32.24.10|32.48.17|36.14.21","13":"10.14.23|11.16.4|32.2.20","14":"32.6.8"}},{"v":["І було до мене слово Господнє:","і ти, сину людський, [скажи]: так говорить Господь Бог; землі Ізраїлевій кінець, — кінець прийшов на чотири краї землі.","Ось кінець тобі; і пошлю на тебе гнів Мій, і буду судити тебе за шляхами твоїми, і покладу на тебе всі мерзоти твої.","І не пощадить тебе око Моє, і не помилую, і воздам тобі за шляхами твоїми, і мерзоти твої з тобою будуть, і пізнаєте, що Я Господь.","Так говорить Господь Бог: біда єдина, ось, іде біда.","Кінець прийшов, прийшов кінець, встав на тебе; ось дійшла,","дійшла напасть до тебе, жителю землі! надходить час, наближається день сум’яття, а не веселих вигуків на горах.","Ось, незабаром виллю на тебе лють Мою і звершу над тобою гнів Мій, і буду судити тебе за шляхами твоїми, і покладу на тебе всі мерзоти твої.","І не пощадить тебе око Моє, і не помилую. За шляхами твоїми воздам тобі, і мерзоти твої з тобою будуть; і пізнаєте, що Я Господь каратель.","Ось день! ось прийшла, настала напасть! жезл виріс, гордість розрослася.","Постає сила на жезл нечестя; нічого не залишиться від них, і від багатства їх, і від шуму їх, і від пишноти їх.","Прийшов час, настав день: хто купив, не радій, і хто продав, не плач; бо гнів над усією безліччю їх;","Бо хто продав, не повернеться до проданого, хоч би і залишилися вони у живих; бо пророче видіння про всю безліч їх не відміниться, і ніхто своїм беззаконням не укріпить свого життя.","Засурмлять у трубу, і все готується, але ніхто не йде на війну: бо гнів Мій над усією безліччю їх.","Поза домом меч, а у домі моровиця і голод. Хто у полі, той помре від меча; а хто у місті, того пожеруть голод і моровиця.","А вцілілі з них утечуть і будуть на горах, як голуби долин; усі вони будуть стогнати, кожен за своє беззаконня.","У всіх руки опустяться, й у всіх коліна затремтять, як вода.","Тоді вони опережуться веретищем, і обійме їх трепет і у всіх на лицях буде сором, і у всіх на головах пліш.","Срібло своє вони викинуть на вулиці, і золото у них буде у зневазі. Срібло їх і золото їх не у змозі буде врятувати їх у день гніву Господа. Вони не наситять ними душ своїх і не наповнять утроб своїх; бо воно було приводом до беззаконня їх.","І у червоних убраннях своїх вони перетворювали його на гордість, і робили з нього зображення мерзотних своїх ідолів; за те і зроблю його нечистим для них;","і віддам його у руки чужих у здобич і беззаконникам землі на розкрадання, і вони осквернять його.","І відверну від них лице Моє, і осквернять потаємне Моє; і прийдуть туди грабіжники, і осквернять його.","Зроби ланцюг, бо земля ця наповнена кривавими злодіяннями, і місто повне насильства.","Я приведу найлютіших з народів, і заволодіють домами їхніми. І покладу кінець пихатості сильних, і будуть осквернені святині їхні.","Йде пагуба; будуть шукати миру, і не знайдуть.","Біда піде за бідою і звістка за звісткою; і будуть просити у пророка видіння, і не стане вчення у священика і поради у старців.","Цар буде ремствувати, і князь одягнеться у жах, і в народу землі будуть тремтіти руки. Вчиню з ними за шляхами їхніми, і за судами їхніми буду судити їх; і пізнають, що Я Господь."],"x":{"2":"33.4.18","8":"36.22.31","9":"36.8.18","10":"39.2.2","15":"33.1.20|36.5.12","16":"31.38.14","17":"36.21.7","18":"31.15.2-3|32.48.37","19":"24.20.20|26.10.2|30.5.10|46.1.18","21":"31.1.7|32.6.12|38.7.9","25":"32.8.11","26":"31.29.14","27":"4.28.59|31.29.14|32.29.17"}},{"v":["І було у шостому році, у шостому місяці, у п’ятий день місяця, сидів я у домі моєму, і старійшини юдейські сиділи перед лицем моїм, і зійшла на мене там рука Господа Бога.","І побачив я: і ось подоба [мужа], ніби вогненна, і від стегон його і нижче — вогонь, і від стегон його і вище — ніби сяйво, ніби світло полум’я.","І простяг Він ніби руку, і взяв мене за волосся голови моєї, і підняв мене дух між землею і небом, і приніс мене у видіннях Божих у Єрусалим до входу внутрішніх воріт, обернених на північ, де був поставлений ідол ревнощів, що збуджує ревнощі.","І ось, там була слава Бога Ізраїлевого, подібна до тієї, яку я бачив на полі.","І сказав мені: сину людський! підніми очі твої до півночі. І я звів очі мої до півночі, і ось, з північного боку біля воріт жертовника — той ідол ревнощів біля входу.","І сказав Він мені: сину людський! чи бачиш ти, що вони роблять? великі мерзоти, які робить дім Ізраїлів тут, щоб Я відійшов від святилища Мого? але повернися, і ти побачиш ще більші мерзоти.","І привів мене до входу у двір, і я глянув, і ось у стіні щілина.","І сказав мені: сину людський! прокопай стіну; і я прокопав стіну, і ось якісь двері.","І сказав мені: ввійди і подивися на огидні мерзоти, які вони роблять тут.","І ввійшов я, і бачу, і ось усякі зображення плазунів і нечистих тварин і всякі ідоли дому Ізраїлевого, написані по стінах навколо.","І сімдесят чоловіків зі старійшин дому Ізраїлевого стоять перед ними, й Ієзанія, син Сафанів, серед них; і у кожного в руці своє кадило, і густа хмара куріння підноситься догори.","І сказав мені: чи бачиш, сину людський, що роблять старійшини дому Ізраїлевого у темряві, кожен у розписаній своїй кімнаті? бо говорять: «не бачить нас Господь, залишив Господь землю цю».","І сказав мені: повернися, і побачиш ще більші мерзоти, які вони роблять.","І привів мене до входу у ворота дому Господнього, які на північ, і ось, там сидять жінки, які плачуть за Фаммугою,","і сказав мені: чи бачиш, сину людський? повернися, і ще побачиш більші мерзоти.","І ввів мене у внутрішній двір дому Господнього, і ось біля дверей храму Господнього, між притвором і жертовником, близько двадцяти п’яти чоловіків стоять спинами своїми до храму Господнього, а обличчями своїми на схід, і кланяються на схід сонця.","І сказав мені: чи бачиш, сину людський? чи мало дому Іудиному, щоб робити такі мерзоти, які вони роблять тут? але вони ще землю наповнили нечестям, і подвійно прогнівляють Мене; і ось, вони віття підносять до носів своїх.","За те і Я буду діяти з люттю; не пошкодує око Моє, і не помилую; і хоч би вони волали у вуха Мої гучним голосом, не почую їх."],"x":{"1":"36.14.1","2":"36.1.27","3":"37.5.5","4":"36.3.23","5":"32.7.30|11.21.7","10":"62.1.23|2.26.30|4.27.15","11":"4.10.8|32.23.11","12":"36.9.9","16":"36.11.1|4.17.3","18":"36.5.11|31.1.15|32.11.11"}},{"v":["І виголосив у вуха мої великим гласом, говорячи: нехай наблизяться карателі міста, кожен зі своїм згубним знаряддям у руці своїй.","І ось, шість чоловік ідуть від верхніх воріт, звернених на північ, і в кожного в руці згубне знаряддя його, і між ними один, одягнений у лляний одяг, у якого при поясі його приладдя писаря. І прийшли і стали біля мідного жертовника.","І слава Бога Ізраїлевого зійшла з херувима, на якому була, до порогу дому. І прикликав Він чоловіка, одягненого у лляний одяг, у якого при поясі приладдя писаря.","І сказав йому Господь: пройди посередині міста, посередині Єрусалима, і на чолах людей скорботних, що зітхають за всіма мерзотами, що звершуються серед нього, зроби знак.","А тим сказав так, що я чув: ідіть за ним по місту й уражайте; нехай не шкодує око ваше, і не щадіть;","старого, юнака і дівчину, і немовля і жінок бийте до смерти, але не чіпайте жодної людини, на якій знак, і почніть від святилища Мого. І почали вони з тих старійшин, які були перед домом.","І сказав їм: оскверніть дім, і наповніть двори убитими, і вийдіть. І вийшли, і почали убивати у місті.","І коли вони їх убили, а я залишився, тоді я упав на лице своє і заволав, і сказав: о, Господи Боже! невже Ти погубиш весь залишок Ізраїля, виливаючи гнів Твій на Єрусалим?","І сказав Він мені: нечестя дому Ізраїлевого й Іудиного велике, дуже велике; і земля ця повна крови, і місто сповнене неправди; бо вони говорять: «залишив Господь землю цю, і не бачить Господь».","За те і Моє око не пощадить, і не помилую; оберну поведінку їх на їх голову.","І ось чоловік, одягнений у лляний одяг, у якого при поясі приладдя писаря, дав відповідь і сказав: я зробив, як Ти повелів мені."],"x":{"2":"36.10.2","3":"36.1.4|36.10.4","4":"76.7.3","5":"1.32.27","6":"33.5.14|32.25.29|56.4.17","8":"36.11.13","9":"36.8.12","10":"36.5.11|36.11.21","11":"36.9.2"}},{"v":["І бачив я, і ось на склепінні, що над Главами херувимів, ніби камінь сапфір, ніби щось, схоже на престіл, видиме було над ними.","І говорив Він чоловікові, одягненому у лляний одяг, і сказав: увійди між колесами під херувимів і візьми повні пригорщі палаючого вугілля між херувимами, і кинь на місто; і він увійшов на моїх очах.","Херувими ж стояли праворуч від дому, коли ввійшов той чоловік, і хмара наповнювала внутрішній двір.","І піднялася слава Господня з херувима до порогу дому, і дім наповнився хмарою, і двір наповнився сяйвом слави Господа.","І шум від крил херувимів чутно було навіть на зовнішньому дворі, ніби глас Бога Всемогутнього, коли Він говорить.","І коли Він дав повеління чоловікові, одягненому у лляний одяг, сказавши: «візьми вогню між колесами, між херувимами», і коли він увійшов і став біля колеса, —","тоді із середовища херувимів один херувим простягнув руку свою до вогню, який між херувимами, і взяв і дав у пригорщі одягненому у лляний одяг. Він узяв і вийшов.","І видно було у херувимів подобу рук людських під крилами їх.","І бачив я: і ось чотири колеса біля херувимів, по одному колесу біля кожного херувима, і колеса на вигляд ніби з каменю топаза.","І на вигляд усі чотири подібні, начебто колесо знаходилося у колесі.","Коли йшли вони, то йшли на чотири свої боки; під час ходи своєї не поверталися, але до того місця, куди повернена була голова, і вони туди йшли; під час ходи своєї не поверталися.","І все тіло їх, і спина їх, і руки їх, і крила їх, і колеса навколо були повні очей, усі чотири колеса їх.","До коліс цих, як я чув, було сказано: «галгал»*.","І у кожної з тварин чотири лиця: перше лице — лице херувимове, друге лице — лице людське, третє лице левове і четверте лице орлине.","Херувими піднялися. Це були ті самі тварини, яких я бачив біля ріки Ховарі.","І коли йшли херувими, тоді йшли поряд з ними і колеса; і коли херувими піднімали крила свої, щоб піднятися від землі, і колеса не відокремлювалися, а були при них.","Коли ті стояли, стояли і вони; коли ті піднімалися, піднімалися і вони; бо у них був дух тварин.","І відійшла слава Господня від порогу дому і стала над херувимами.","І підняли херувими крила свої, і піднялися на очах моїх від землі; коли вони відходили, то і колеса поряд з ними; і стали біля входу у східні врата дому Господнього, і слава Бога Ізраїлевого вгорі над ними.","Це були ті самі тварини, яких бачив я біля підніжжя Бога Ізраїлевого біля ріки Ховарі. І я пізнав, що це херувими.","У кожного по чотири лиця, й у кожного по чотири крила, і під крилами їх подоба рук людських.","А подоба лиць їх те саме, які лиця бачив я біля ріки Ховарі, — і вигляд їх, і самі вони. Кожен ішов прямо у той бік, який був перед лицем його."],"x":{"1":"36.1.26","2":"36.9.2|25.17.9","4":"31.6.4|36.9.3|36.43.4","6":"36.9.2","9":"36.1.15-16","12":"36.1.15|76.4.6","14":"36.1.6|36.41.19","15":"36.1.3","17":"36.1.19-20","18":"36.11.23","20":"36.1.3","21":"36.1.6"},"n":{"13":["Вихор."]}},{"v":["І підняв мене дух, і привів мене до східних воріт дому Господнього, які повернені на схід. І ось, біля входу у ворота двадцять п’ять чоловік; і між ними я бачив Іазанію, сина Азурового, і Фалтію, сина Ванеєвого, князів народу.","І Він сказав мені: сину людський! ось люди, у яких на думці беззаконня і які дають злу пораду у місті цьому,","говорячи: «ще не близько; будемо будувати доми; воно* казан, а ми м’ясо».","Тому проречи на них пророцтво, пророкуй, сину людський.","І зійшов на мене Дух Господній і сказав мені: скажи, так говорить Господь: що говорите ви, доме Ізраїлів, і що на думку вам приходить, це Я знаю.","Багато вбитих ваших ви поклали у цьому місті і вулиці його наповнили трупами.","Тому так говорить Господь Бог: убиті ваші, яких ви поклали серед нього, є м’ясо, а воно — казан; але вас Я виведу з нього.","Ви боїтеся меча, і Я наведу на вас меч, — говорить Господь Бог.","І виведу вас з нього, і віддам вас у руки чужих, і вчиню над вами суд.","Від меча впадете; на межах Ізраїлевих будуть судити вас, і пізнаєте, що Я Господь.","Воно не буде для вас казаном, і ви не будете м’ясом у ньому; на межах Ізраїлевих буду судити вас.","І пізнаєте, що Я Господь; бо за заповідями Моїми ви не ходили й уставів Моїх не виконували, а жили за уставами народів, які оточують вас.","І було, коли я пророкував, Фалтія, син Ванеїв, помер. І упав я на лице, і заволав гучним голосом, і сказав: о, Господи Боже! невже Ти хочеш до кінця знищити залишок Ізраїлю?","І було до мене слово Господнє:","сину людський! твоїм братам, твоїм братам, твоїм єдинокровним і всьому дому Ізраїлевому, усім їм говорять ті, що живуть у Єрусалимі: «живіть далеко від Господа; нам у володіння віддана ця земля».","На це скажи: так говорить Господь Бог: хоч Я і віддалив їх до народів і хоч розсіяв їх по землях, але Я буду для них якимось святилищем у тих землях, куди пішли вони.","Потім скажи: так говорить Господь Бог: Я зберу вас із народів, і поверну вас із земель, в яких ви розсіяні; і дам вам землю Ізраїлеву.","І прийдуть туди, і викинуть з неї всі мерзоти її і всі гидоти її.","І дам їм серце єдине, і дух новий вкладу в них, і візьму з плоті їх серце кам’яне, і дам їм серце плотське,","щоб вони ходили за заповідями Моїми, і дотримувалися уставів Моїх, і виконували їх; і будуть Моїм народом, а Я буду їхнім Богом.","А чиє серце захопиться мерзотами їх і гидотами їх, поведінку тих оберну на їхню голову, — говорить Господь Бог.","Тоді херувими підняли крила свої, і колеса поряд з ними; і слава Бога Ізраїлевого вгорі над ними.","І піднялася слава Господа із середовища міста і зупинилася над горою, яка на схід від міста.","І дух підняв мене і переніс мене у Халдею, до переселенців, у видінні, Духом Божим. І відійшло від мене видіння, яке я бачив.","І я переказав переселенцям усі слова Господа, які Він відкрив мені."],"x":{"1":"36.8.3:16","8":"26.10.24","10":"11.25.21|32.39.6|32.52.10","12":"36.5.6-7","13":"3.16.45|36.9.8","15":"32.21.13","16":"31.57.13|48.8.13|46.3.17","17":"32.23.3","19":"32.24.7|32.32.39|36.18.31|36.36.26","20":"36.36.28","21":"36.9.10","23":"36.10.18","24":"36.8.3"},"n":{"3":["Місто."]}},{"v":["І було до мене слово Господнє:","сину людський! ти живеш серед дому бунтівного; у них є очі, щоб бачити, а не бачать; у них є вуха, щоб чути, а не чують; тому що вони — бунтівний дім.","Ти ж, сину людський, приготуй собі потрібне для переселення, і серед дня переселяйся перед очима їхніми, і переселяйся з місця твого в інше місце перед очима їхніми; можливо, вони зрозуміють, хоч вони — дім бунтівний;","і речі твої винеси, як речі потрібні при переселенні, вдень, перед очима їхніми, і сам вийди ввечері перед очима їхніми, як виходять для переселення.","Перед очима їхніми проламай собі отвір у стіні, і винеси через нього.","Перед очима їхніми візьми ношу на плече, у потемках винеси її, лице твоє закрий, щоб не бачити землі; бо Я поставив тебе знаменням дому Ізраїлевому.","І зробив я, як повелено було мені; речі мої, як речі потрібні при переселенні, виніс удень, а ввечері проламав собі рукою отвір у стіні, у потемках виніс ношу і підняв на плече перед очима їхніми.","І було до мене слово Господнє зранку:","сину людський! чи не говорив тобі дім Ізраїлів, дім бунтівний: «що ти робиш?»","Скажи їм: так говорить Господь Бог: це — провіщення для того, хто начальствує в Єрусалимі, і для всього дому Ізраїлевого, який знаходиться там.","Скажи: я знамення для вас; що роблю я, те буде з ними, — у переселення, у полон підуть вони.","І начальник, який серед них, у потемках підніме ношу на плече і вийде. Стіну проламають, щоб відправити його через неї; він закриє лице своє, так що не побачить очима землі цієї.","І розкину на нього сіть Мою, і буде впійманий у тенета Мої, і відведу його у Вавилон, у землю Халдейську, але він не побачить її, і там помре.","А всіх, які навколо нього, споборників його й усе військо його розвію по усіх вітрах, і оголю услід їм меч.","І пізнають, що Я Господь, коли розсію їх по народах і розвію їх по землях.","Але невелику кількість їх Я збережу від меча, голоду і моровиці, щоб вони розповіли народам, до яких підуть, про всі свої мерзоти; і пізнають, що Я Господь.","І було до мене слово Господнє:","сину людський! хліб твій їж з трепетом, і воду твою пий із тремтінням і сумом.","І скажи народу землі: так говорить Господь Бог про жителів Єрусалима, про землю Ізраїлеву: вони хліб свій будуть їсти із сумом і воду свою будуть пити у тузі, тому що земля його буде позбавлена всього достатку свого за неправди всіх, що живуть на ній.","І будуть розорені населені міста, і земля зробиться порожньою, і пізнаєте, що Я Господь.","І було до мене слово Господнє:","сину людський! що за приказка у вас, у землі Ізраїлевій: «багато днів мине, і всяке пророче видіння зникне»?","Тому скажи їм: так говорить Господь Бог: знищу цю приказку, і не будуть уже вживати такої приказки в Ізраїлі; але скажи їм: близькі дні і сповнення всякого видіння пророчого.","Бо вже не залишиться марним ніяке видіння пророче, і жодне пророкування не буде неправдивим у домі Ізраїлевім.","Бо Я Господь, Я говорю; і слово, яке Я говорю, сповниться, і не буде відкладене; у ваші дні, бунтівний доме, Я прорік слово, і виконаю його, — говорить Господь Бог.","І було до мене слово Господнє:","сину людський! ось, дім Ізраїлів говорить: «пророче видіння, яке бачив він, збудеться після багатьох днів, і він пророкує про віддалені часи».","Тому скажи їм: так говорить Господь Бог: жодне зі слів Моїх уже не буде відстрочене, але слово, яке Я скажу, збудеться, — говорить Господь Бог."],"x":{"2":"32.5.21","3":"32.26.3|32.36.3","6":"36.24.24","9":"32.23.33","12":"32.52.7|40.4.3","13":"36.17.20|36.32.3|11.25.7","14":"36.5.12","15":"36.22.5","16":"31.4.3|48.13.8","18":"36.4.16|38.9.4|25.126.2","19":"36.4.16","20":"32.4.27|32.9.11|43.6.13","22":"45.2.3|57.3.4|32.17.15","23":"38.1.4","24":"3.23.19|8.3.19|31.34.16","27":"36.11.3"}},{"v":["І було до мене слово Господнє:","сину людський! проречи пророцтво на пророків Ізраїлевих, які пророкують, і скажи пророкам від власного серця: слухайте слово Господнє!","Так говорить Господь Бог: горе безумним пророкам, які водяться своїм духом і нічого не бачили!","Пророки твої, Ізраїлю, як лисиці у руїнах.","У проломи ви не входите і не обгороджуєте стіною дому Ізраїлевого, щоб твердо стояти у битві у день Господа.","Вони бачать пусте і передвіщають неправду, говорячи: «Господь сказав»; а Господь не посилав їх; і дають надію, що слово збудеться.","Чи не пусте видіння бачили ви? і чи не облудне пророкування прорікаєте, говорячи: «Господь сказав», а Я не говорив?","Тому так говорить Господь Бог: оскільки ви говорите пусте і бачите у видіннях неправду, за те ось Я — проти вас, говорить Господь Бог.","І буде рука Моя проти цих пророків, які бачать пусте і передвіщають неправду; у раді народу Мого вони не будуть, і до списку дому Ізраїлевого не впишуться, і в землю Ізраїлеву не ввійдуть; і пізнаєте, що Я Господь Бог.","За те, що вони вводять народ Мій в оману, говорячи: «мир», тоді як немає миру; і коли він будує стіну, вони обмазують її брудом,","скажи тим, хто обмазує стіну багном, що вона впаде. Піде злива, і ви, кам’яні градини, впадете, і бурхливий вітер розірве її.","І ось, упаде стіна; тоді чи не скажуть вам: «де та обмазка, якою ви обмазували?»","Тому так говорить Господь Бог: Я пущу бурхливий вітер у гніві Моєму, і піде злива у люті Моїй, і камені граду в обуренні Моєму, для знищення.","І зруйную стіну, яку ви обмазували багном, і повалю її на землю, і відкриється основа її, і впаде, і ви разом з нею загинете; і пізнаєте, що Я Господь.","І виснажу лють Мою на стіні і на тих, хто обмазує її багном, і скажу вам: немає стіни, і немає тих, які обмазували її,","пророків Ізраїлевих, які пророкували Єрусалиму і звіщали йому видіння миру, тоді як немає миру, — говорить Господь Бог.","Ти ж, сину людський, оберни лице твоє до дочок народу твого, які пророкують від власного свого серця, і виречи на них пророцтво,","і скажи: так говорить Господь Бог: горе тим, що зшивають чаклунські мішечки під пахви і роблять покривала для голови усякого зросту, щоб уловлювати душі! Невже, уловлюючи душі народу Мого, ви спасете ваші душі?","І неславите Мене перед народом Моїм за жмені ячменю і за шматки хліба, умертвлюючи душі, які не повинні померти, і залишаючи життя душам, які не повинні жити, обманюючи народ, який слухає неправду.","Тому так говорить Господь Бог: ось, Я — на ваші чаклунські мішечки, якими ви там уловлюєте душі, щоб вони прилітали, і вирву їх з-під м’язів ваших, і випущу на волю душі, які ви уловлюєте, щоб прилітали до вас.","І роздеру покривала ваші, і визволю народ Мій від рук ваших, і не будуть уже у ваших руках здобиччю, і пізнаєте, що Я Господь.","За те, що ви неправдою засмучуєте серце праведника, яке Я не хотів засмучувати, і підтримуєте руки беззаконника, щоб він не навернувся від порочної путі своєї і не зберіг життя свого, —","за це вже не будете мати пустих видінь і надалі не будете угадувати; і Я визволю народ Мій від рук ваших, і пізнаєте, що Я Господь."],"x":{"2":"32.23.1|33.2.14|64.2.17","3":"36.14.9","4":"28.2.15","5":"36.22.30","6":"32.5.31","7":"32.14.14","9":"48.13.4","10":"32.6.14","11":"31.28.17","16":"32.6.14|32.8.11|36.13.10","18":"43.3.5|62.16.18|72.3.6","19":"46.3.4|56.5.2|26.17.15","22":"32.23.14"}},{"v":["І прийшли до мене кілька людей зі старійшин Ізраїлевих і сіли перед лицем моїм.","І було до мене слово Господнє:","сину людський! Ці люди впустили ідолів своїх у серце своє і поставили спокусу нечестя свого перед лицем своїм: чи можу Я відповідати їм?","Тому говори з ними і скажи їм: так говорить Господь Бог: якщо хто з дому Ізраїлевого впустить ідолів своїх у серце своє і поставить спокусу нечестя свого перед лицем своїм, і прийде до пророка, — то Я, Господь, чи можу, при безлічі ідолів його, дати йому відповідь?","Нехай дім Ізраїлів зрозуміє в серці своєму, що усі вони через своїх ідолів зробилися чужими для Мене.","Тому скажи дому Ізраїлевому: так говорить Господь Бог: наверніться і відверніться від ідолів ваших, і від усіх мерзот ваших відверніть лице ваше.","Бо якщо хто з дому Ізраїлевого і з прибульців, які живуть у Ізраїля, відійде від Мене і допустить ідолів своїх у серце своє, і поставить спокусу нечестя свого перед лицем своїм, і прийде до пророка запитати Мене через нього, — то Я, Господь, чи дам йому відповідь від Себе?","Я поверну лице Моє проти тієї людини і скрушу її на знамення і притчу, і знищу її з народу Мого, і пізнаєте, що Я Господь.","А якщо пророк допустить звабити себе і скаже слово так, ніби Я, Господь, навчив цього пророка, то Я простягну на нього руку Мою і знищу його з народу Мого, Ізраїля.","І понесуть провину беззаконня свого: яка провина того, хто запитує, така буде провина і пророка,","щоб надалі дім Ізраїлів не ухилявся від Мене і щоб більше не оскверняли себе всякими беззаконнями своїми, але щоб були Моїм народом, і Я був їхнім Богом, — говорить Господь Бог.","І було до мене слово Господнє:","сину людський! якби яка земля згрішила переді Мною, віроломно відступивши від Мене, і Я простяг на неї руку Мою, і знищив у ній хлібну опору, і послав на неї голод, і став губити на ній людей і худобу;","і якби знайшлися у ній ці три мужі: Ной, Даниїл та Іов, — то вони праведністю своєю спасли б тільки свої душі, — говорить Господь Бог.","Або, якби Я послав на цю землю лютих звірів, які осиротили б її, і вона через звірів зробилася б пустелею непрохідною:","то ці три мужі серед неї, — живу Я, — говорить Господь Бог, — не спасли б ні синів, ні дочок, а вони, тільки вони спаслися б, земля ж зробилася б пустелею.","Або, якби Я навів на ту землю меч і сказав: «меч, пройди по землі!», і став знищувати на ній людей і худобу,","то ці три мужі серед неї, — живу Я, — говорить Господь Бог, — не спасли б ні синів, ні дочок, а вони тільки спаслися б.","Або, якби Я послав на ту землю моровицю і вилив на неї лють Мою у кровопролитті, щоб знищити на ній людей і худобу:","то Ной, Даниїл та Іов серед неї, — живу Я, — говорить Господь Бог, — не спасли б ні синів, ні дочок; праведністю своєю вони спасли б тільки свої душі.","Бо так говорить Господь Бог: якщо і чотири тяжкі кари Мої: меч, і голод, і лютих звірів, і моровицю пошлю на Єрусалим, щоб знищити у ньому людей і худобу,","і тоді залишиться в ньому залишок, сини і дочки, які будуть виведені звідти; ось, вони вийдуть до вас, і ви побачите поведінку їхню і діла їхні, і утішитеся у тій біді, яку Я навів на Єрусалим, у всьому, що Я навів на нього.","Вони утішать вас, коли ви побачите поведінку їхню й діла їхні; і пізнаєте, що Я недарма зробив усе те, що зробив у ньому, — говорить Господь Бог."],"x":{"1":"36.8.1|36.20.1","3":"32.8.5|36.20.3","7":"46.1.6","8":"4.28.37|36.5.15","9":"36.13.3","11":"1.19.5|2.26.12|36.36.28","13":"36.4.16|36.5.16","14":"32.15.1|57.2.5|24.42.8","15":"2.26.22|36.5.17","21":"2.26.16|32.24.10|36.5.17","22":"32.4.27"}},{"v":["І було до мене слово Господнє:","сину людський! яку перевагу має дерево виноградної лози перед усяким іншим деревом і віття виноградної лози — між деревами у лісі?","Чи беруть від нього шматок на який-небудь виріб? Чи беруть від нього хоч на цвях, щоб вішати на ньому яку-небудь річ?","Ось, воно віддається вогню на спалення; обидва кінці його вогонь поїв, і обгоріла середина його: чи годиться воно на який-небудь виріб?","І тоді, коли воно було цілим, не годилося ні на який виріб; тим більше, коли вогонь поїв його, і воно обгоріло, чи годиться воно на який-небудь виріб?","Тому так говорить Господь Бог: як дерево виноградної лози між деревами лісовими Я віддав вогню на спалення, так віддам йому і жителів Єрусалима.","І поверну лице Моє проти них; з одного вогню вийдуть, і інший вогонь пожере їх, — і пізнають, що Я Господь, коли оберну проти них лице Моє.","І зроблю цю землю пустелею за те, що вони віроломно чинили, — говорить Господь Бог."],"x":{"4":"9.23.6|53.15.6"}},{"v":["І було до мене слово Господнє:","сину людський! вислови Єрусалиму мерзоти його","і скажи: так говорить Господь Бог дочці Єрусалима: твій корінь і твоя батьківщина у землі Ханаанській; батько твій аморрей, і мати твоя хеттеянка;","при народженні твоєму, у день, коли ти народилася, пуповину твою не відрізали, і водою ти не була обмита для очищення, і сіллю не була осолена, і пеленами не повита.","Нічиє око не зглянеться на тебе, щоб з милости до тебе зробити тобі що-небудь з цього; але ти викинута була на поле, з презирства до життя твого, у день народження твого.","І проходив Я мимо тебе, і побачив тебе, покинуту на потоптання в кровя́х твоїх, і сказав тобі: «у кровя́х твоїх живи!» Так, Я сказав тобі: «у кровя́х твоїх живи!»","Примножив тебе, як польові рослини; ти виросла і стала великою, і досягла чудової краси: піднялися груди, і волосся у тебе виросло; але ти була нага і непокрита.","І проходив Я мимо тебе, і побачив тебе, і ось, це був час твій, час любови; і простер Я крила риз Моїх на тебе, і покрив наготу твою; і поклявся тобі і вступив у союз з тобою, — говорить Господь Бог, — і ти стала Моєю.","Обмив Я тебе водою і змив з тебе кров твою і помазав тебе єлеєм.","І надів на тебе візерунчасте плаття, і взув тебе в сап’янові сандалії, й оперезав тебе висоном, і покрив тебе шовковим покривалом.","І убрав тебе в убрання, і поклав на руки твої зап’ястя і на шию твою намисто.","І дав тобі кільце на твій ніс і серги на вуха твої і на голову твою прекрасний вінець.","Так прикрашалася ти золотом і сріблом, і одяг твій був висон і шовк і візерунчасті тканини; годувалася ти хлібом із кращого пшеничного борошна, медом і єлеєм, і була надзвичайно красива, і досягла царственої величі.","І пронеслася між народами слава твоя заради краси твоєї, тому що вона була цілком досконала при тому чудовому убранні, яке Я поклав на тебе, — говорить Господь Бог.","Але ти понадіялася на красу твою, і, користуючись славою твоєю, стала блудити і поширювала блудодійство твоє на кожного, хто проходив мимо, віддаючись йому.","І взяла з одягу твого, і зробила собі різнобарвні висоти, і блудодіяла на них, як ніколи не трапиться і не буде.","І взяла ошатні твої речі з Мого золота і з Мого срібла, яке Я дав тобі, і зробила собі чоловічі зображення, і блудодіяла з ними.","І взяла візерунчасті плаття твої, і одягла їх ними, і ставила перед ними єлей Мій і фіміам Мій,","і хліб Мій, який Я давав тобі, пшеничне борошно, і єлей, і мед, якими Я годував тебе, ти ставила перед ними як приємні пахощі; і це було, — говорить Господь Бог.","І взяла синів твоїх і дочок твоїх, яких ти народила Мені, і приносила у жертву на споживання їм. Чи мало було для тебе блудодіяти?","Але ти і синів Моїх заколювала і віддавала їм, проводячи їх через вогонь.","І при усіх твоїх мерзотах і блудодіяннях твоїх ти не згадала про дні юности твоєї, коли ти була нага і непокрита і покинута у крові твоїй на потоптання.","І після всіх злодіянь твоїх, — горе, горе тобі! — говорить Господь Бог, —","ти побудувала собі блудилища і наробила собі підвищень на всякій площі;","біля початку всякої дороги влаштувала собі узвишшя, ганьбила красу твою і розкидала ноги твої для всякого перехожого, і примножила блудодіяння твої.","Блудила із синами Єгипту, сусідами твоїми, людьми великорослими, і примножувала блудодіяння твої, прогнівляючи Мене.","І ось, Я простяг на тебе руку Мою, і зменшив призначене тобі, і віддав тебе на сваволю дочкам филистимським, які ненавидять тебе, які посоромилися соромітної поведінки твоєї.","І блудила ти із синами Ассура і не наситилася; блудила з ними, але тим не задовольнилася;","і примножила блудодіяння твої у землі Ханаанській до Халдеї, але і тим не задовольнилась.","Яким стомленим повинно бути серце твоє, — говорить Господь Бог, — коли ти все це робила, як неприборкана блудниця!","Коли ти будувала собі блудилища біля початку всякої дороги і робила собі узвишшя на всякій площі, ти була не як блудниця, тому що відкидала подарунки,","але як перелюбна дружина, яка приймає замість свого чоловіка чужих.","Усім блудницям дають подарунки, а ти сама давала подарунки всім коханцям твоїм і підкуповувала їх, щоб вони з усіх боків приходили до тебе блудити з тобою.","У тебе у блудодіяннях твоїх було супротивне тому, що буває у жінок: не за тобою ганялися, але ти давала подарунки, а тобі не давали подарунків; і тому ти чинила на противагу іншим.","Тому вислухай, блуднице, слово Господнє!","Так говорить Господь Бог: за те, що ти так розсипала гроші твої, і у блудодіяннях твоїх розкрита була нагота твоя перед коханцями твоїми і перед усіма мерзенними ідолами твоїми, і за кров синів твоїх, яких ти віддавала їм, —","за те ось, Я зберу всіх коханців твоїх, якими ти насолоджувалась і яких ти кохала, з усіма тими, яких ненавиділа, і зберу їх звідусіль проти тебе, і розкрию перед ними наготу твою, і побачать увесь сором твій.","Я буду судити тебе судом перелюбниць і тих, хто проливає кров, — і віддам тебе кривавій люті і ревнощам;","віддам тебе у руки їх і вони зруйнують блудилища твої, і розкидають узвишшя твої, і зірвуть з тебе одяг твій, і візьмуть убрання твоє, і залишать тебе нагою і непокритою.","І скличуть на тебе зібрання, і поб’ють тебе камінням, і розрубають тебе мечами своїми.","Спалять доми твої вогнем і вчинять над тобою суд перед очима багатьох дружин; і покладу кінець блуду твоєму, і не будеш уже давати подарунків.","І вгамую на тобі гнів Мій, і відступить від тебе обурення Моє, і заспокоюся, і вже не буду гніватися.","За те, що ти не згадала про дні юности твоєї і всім цим гнівала Мене, ось, і Я поведінку твою оберну на твою голову, — говорить Господь Бог, — щоб ти не віддавалася більш розпусті після всіх твоїх мерзот.","Ось, усякий, хто говорить притчами, може сказати про тебе: «яка мати, така і дочка».","Ти дочка у матір твою, яка покинула чоловіка свого і дітей своїх, — і ти сестра у сестер твоїх, які покинули чоловіків своїх і дітей своїх. Мати ваша хеттеянка, і батько ваш аморрей.","Більша ж сестра твоя — Самарія, що з дочками своїми живе наліво від тебе; а менша сестра твоя, що живе від тебе направо, є Содома з дочками її.","Але ти і не їхніми путями ходила і не за їхніми мерзотами чинила; цього було мало: ти чинила розпусніше за них на всіх путях твоїх.","Живу Я, — говорить Господь Бог; Содома, сестра твоя, не робила того сама і її дочки, що робила ти і дочки твої.","Ось у чому було беззаконня Содоми, сестри твоєї, і дочок її: у гордості, пересиченні й ліності, і вона руки бідного й убогого не підтримувала.","І загордилися вони, і робили мерзоти перед лицем Моїм, і, побачивши це, Я відкинув їх.","І Самарія половини гріхів твоїх не нагрішила; ти перевершила їх мерзотами твоїми, і через твої мерзоти, які робила ти, сестри твої виявилися правішими за тебе.","Неси ж посоромлення твоє і ти, яка осуджувала сестер твоїх; за гріхами твоїми, якими ти зганьбила себе більше за них, вони правіші за тебе. Червоній же від сорому і ти, і неси посоромлення твоє, так виправдавши сестер твоїх.","Але Я поверну полон їх, полон Содоми і дочок її, полон Самарії і дочок її, і між ними полон полонених твоїх,","щоб ти несла посоромлення твоє і соромилась усього того, що робила, слугуючи для них утішенням.","І сестри твої, Содома і дочки її, повернуться у попередній стан свій; і Самарія і дочки її повернуться у попередній стан свій, і ти і дочки твої повернетеся у попередній стан ваш.","Про сестру твою Содому і спомину не було у вустах твоїх у дні гордині твоєї,","доки ще не відкрито було нечестя твоє, як у час посоромлення від дочок Сирії і всіх, хто оточував її, від дочок Филистими, які дивилися на тебе з презирством з усіх боків.","За розпусту твою і за мерзоти твої терпиш ти, — говорить Господь.","Бо так говорить Господь Бог: Я вчиню з тобою, як учинила ти, знехтувавши клятву порушенням союзу.","Але Я згадаю союз Мій з тобою у дні юности твоєї, і відновлю з тобою вічний союз.","І ти згадаєш про путі твої, і буде соромно тобі, коли станеш приймати до себе сестер твоїх, більших за тебе, як і менших за тебе, і коли Я буду давати тобі їх за дочок, але не від твого союзу.","Я відновлю союз Мій з тобою, і пізнаєш, що Я Господь,","для того, щоб ти пам’ятала і соромилася, і щоб надалі не можна було тобі і рота відкрити від сорому, коли Я прощу тобі все, що ти робила, — говорить Господь Бог."],"x":{"2":"31.58.1","3":"0.10.16|0.27.46","6":"52.15.20|40.5.4","7":"76.3.17","8":"1.19.4|38.2.19","10":"31.61.10|76.19.8","12":"31.28.5|26.4.9","13":"52.22.29","15":"31.1.21|38.2.2","16":"38.2.8-9","20":"2.18.21","21":"36.20.31","24":"32.3.2","26":"36.23.20","30":"68.2.11|36.23.44","31":"38.8.11","32":"26.7.19","33":"0.38.16-17","35":"38.5.3","37":"44.3.5","38":"36.23.10","40":"36.23.47","41":"11.25.9|32.52.10","42":"36.5.13","43":"36.9.10","44":"38.2.5","45":"36.16.3","46":"32.3.7|38.2.1|62.9.29","48":"0.18.20","49":"30.16.9|52.17.28","51":"11.17.7|36.23.11","52":"32.3.11","53":"32.29.14|36.39.25","54":"36.5.15","59":"17.10.29","60":"52.1.72|75.8.8","61":"36.36.31","62":"65.4.6","63":"36.6.9|62.6.21"}},{"v":["І було до мене слово Господнє:","сину людський! запропонуй загадку і скажи притчу до дому Ізраїлевого.","Скажи: так говорить Господь Бог: великий орел з великими крилами, з довгими перами, пухнастий, строкатий, прилетів у Ливан і зняв з кедра верхівку,","зірвав верхній з молодих паростків його і приніс його у землю Ханаанську, у місті торговців поклав його;","і взяв від насіння цієї землі, і посадив на землі насіння, помістив біля великих вод, як садять вербу.","І воно виросло, і зробилося виноградною лозою, широкою, низькою на зріст, віття якої хилилося до неї, і коріння її було під нею ж, і стало виноградною лозою, і дало паростки, і пустило віття.","І ще був орел з великими крилами і пухнастий; і ось, ця виноградна лоза потягнулася до нього своїм корінням і простягла до нього віття своє, щоб він поливав її з борозен розсадника свого.","Вона була посаджена на доброму полі, біля великих вод, так що могла пускати віття і приносити плід, зробитися лозою чудовою.","Скажи: так говорить Господь Бог: чи буде у неї успіх? Чи не вирвуть коренів її, і чи не обірвуть плодів її, так що вона засохне? усе молоде віття, яке виросло від неї, засохне. І не з великою силою і не з багатьма людьми зірвуть її з коренів її.","І ось, хоч вона посаджена, але чи буде успіх? Чи не засохне вона, як тільки торкнеться її східний вітер? засохне на грядках, де виросла.","І було до мене слово Господнє:","скажи бунтівному дому: хіба не знаєте, що це означає? — Скажи: ось, прийшов цар Вавилонський у Єрусалим, і взяв царя його і князів його, і привів їх до себе у Вавилон.","І взяв іншого з царського роду, й уклав з ним союз, і зобов’язав його клятвою, і взяв сильних землі тієї із собою,","щоб царство було покірне, щоб не могло піднятися, щоб збережений був союз і стояв твердо.","Але той відійшов від нього, пославши послів своїх у Єгипет, щоб дали йому коней і багато людей. Чи буде йому успіх? Чи вціліє той, хто це робить? Він порушив союз і чи уціліє?","Живу Я, — говорить Господь Бог: у місці перебування царя, який поставив його царем, і якому дану клятву він знехтував, і порушив союз свій з ним, він помре у нього у Вавилоні.","З великою силою і з численним народом фараон нічого не зробить для нього у цій війні, коли буде насипаний вал і будуть побудовані облогові вежі на загибель багатьох душ.","Він знехтував клятву, щоб порушити союз, і ось, дав руку свою і зробив усе це; він не вціліє.","Тому так говорить Господь Бог: живу Я! клятву Мою, яку він знехтував, і союз Мій, який він порушив, Я поверну на його голову.","І закину на нього сіть Мою, і впійманий буде у тенета Мої; і приведу його у Вавилон, і там буду судитися з ним за віроломство його проти Мене.","А всі утікачі його з усіх полків його упадуть від меча, а ті, що залишилися, розвіяні будуть по всіх вітрах; і пізнаєте, що Я, Господь, сказав це.","Так говорить Господь Бог: і візьму Я з вершини високого кедра, і посаджу; з верхніх паростків його відірву ніжну парость і посаджу на високій і величній горі.","На високій горі Ізраїлевій посаджу її, і пустить віття, і принесе плід, і зробиться величним кедром, і будуть жити під ним усякі птахи, усякі пернаті будуть жити у тіні гілок його.","І пізнають усі дерева польові, що Я, Господь, високе дерево понижую, низьке дерево підвищую, дерево, яке зеленіє, висушую, а сухе дерево роблю квітучим: Я, Господь, сказав, і зроблю."],"x":{"2":"36.20.49","3":"37.7.4|38.8.1|36.31.3","10":"36.27.26","12":"11.24.10|13.36.10","13":"32.34.19","15":"11.24.20|31.30.2","16":"11.24.17:20|32.34.3","17":"11.25.1|31.29.3|36.4.2","18":"14.10.19","19":"36.9.10","20":"36.12.13|36.32.3","21":"36.12.14","22":"36.31.3","23":"37.4.9","24":"36.36.36|36.37.14"}},{"v":["І було до мене слово Господнє:","навіщо ви вживаєте у землі Ізраїлевій це прислів’я, говорячи: «батьки їли кислий виноград, а у дітей на зубах оскома»?","Живу Я! — говорить Господь Бог, — не будуть надалі говорити прислів’я це в Ізраїлі.","Бо ось, усі душі — Мої: як душа батька, так і душа сина — Мої: душа, яка згрішає, та помре.","Якщо хто праведний і чинить суд і правду,","на горах жертовного не їсть і до ідолів дому Ізраїлевого не звертає очей своїх, дружини ближнього свого не оскверняє і до своєї дружини під час очищення нечистот її не наближається,","нікого не пригноблює, боржникові повертає заставу його, крадіжки не робить, хліб свій дає голодному і нагого покриває одежею,","у ріст не віддає і лихви не бере, від неправди утримує руку свою, суд людині з людиною чинить правильний,","живе за заповідями Моїми і дотримується постанов Моїх щиро: то він праведник, він неодмінно буде живий, — говорить Господь Бог.","Але якщо у нього народився син розбійник, який проливає кров, і робить що-небудь із усього того,","чого він сам не робив зовсім, і на горах їсть жертовне, і дружину ближнього свого оскверняє,","бідного й убогого утискує, насильно віднімає, заставу не повертає, і до ідолів звертає очі свої, чинить мерзоти,","у ріст дає, і бере лихву; то чи буде він живий? Ні, він не буде живий. Хто робить усі такі мерзоти, той неодмінно помре, кров його буде на ньому.","Але якщо у кого народився син, який, бачачи всі гріхи батька свого, які він робить, бачить і не робить подібного їм:","на горах жертовного не їсть, до ідолів дому Ізраїлевого не звертає очей своїх, дружини ближнього свого не оскверняє,","і людини не пригноблює, застави не бере, і насильно не віднімає, хліб свій дає голодному, і нагого покриває одягом,","від ображання бідного утримує руку свою, росту і лихви не бере, виконує Мої повеління і чинить за заповідями Моїми, — то цей не помре за беззаконня батька свого; він буде живий.","А батько його, оскільки він жорстоко пригноблював, грабував брата і недобре робив серед народу свого, ось, він помре за своє беззаконня.","Ви говорите: «чому ж син не несе провини батька свого?» Тому що син чинить законно і праведно, усіх уставів Моїх дотримується і виконує їх; він буде живий.","Душа, яка грішить, вона вмре; син не понесе провини батька, і батько не понесе провини сина, правда праведного при ньому і залишається, і беззаконня беззаконного при ньому і залишається.","І беззаконник, якщо навернеться від усіх гріхів своїх, які робив, і буде дотримуватися всіх уставів Моїх і чинити законно і праведно, живий буде, не помре.","Усі злочини його, які робив він, не пригадаються йому: у правді своїй, яку буде робити, він живий буде.","Хіба Я хочу смерти беззаконника? — говорить Господь Бог. Чи не того, щоб він повернувся від шляхів своїх і був живий?","І праведник, якщо відступить від правди своєї і буде жити неправедно, буде робити всі ті мерзоти, які робить беззаконник, чи буде він живий? усі добрі діла його, які він робив, не пригадаються; за беззаконня своє, яке робить, і за гріхи свої, у яких грішний, він помре.","Але ви говорите: «неправий путь Господа!» Послухайте, доме Ізраїлів! Чи Мій путь неправий? чи не ваші путі неправі?","Якщо праведник відступає від правди своєї і робить беззаконня і за те помирає, то він помирає за беззаконня своє, яке зробив.","І беззаконник, якщо навертається від беззаконня свого, яке робив, і творить суд і правду, — до життя поверне душу свою.","Бо він побачив і навернувся від усіх злочинів своїх, які робив; він буде живий, не помре.","А дім Ізраїлів говорить: «неправий путь Господа!» чи Мої путі неправі, доме Ізраїлів? чи не ваші путі неправі?","Тому Я буду судити вас, доме Ізраїлів, кожного за шляхами його, — говорить Господь Бог; покайтеся і наверніться від усіх злочинів ваших, щоб нечестя не було вам спотиканням.","Відкиньте від себе всі гріхи ваші, якими згрішили ви, і сотворіть собі нове серце і новий дух; і навіщо вам помирати, доме Ізраїлів?","Бо Я не хочу смерти помираючого, — говорить Господь Бог; але наверніться, і живіть!"],"x":{"2":"32.31.29","4":"4.24.16|62.2.9","6":"2.18.20","7":"1.22.26-27|2.19.13|4.15.7|31.58.7|50.25.35","8":"1.22.25","13":"36.22.12|17.5.7","16":"4.15.8|31.58.7","20":"4.24.16|11.14.6|13.25.4","21":"32.18.8","22":"43.7.19","23":"31.55.7|36.33.11","24":"36.3.20","25":"36.33.17:20","28":"10.12.16","30":"50.3.2","31":"32.32.39|36.11.19","32":"9.14.14|29.1.13|36.33.11"}},{"v":["А ти здійми плач за князями Ізраїля","і скажи: що за левиця мати твоя? розташувалася серед левів, між молодими левами зрощувала левенят своїх.","І вигодувала одного із левенят своїх; він зробився молодим левом і навчився ловити здобич, їв людей.","І почули про нього народи; він упійманий був у яму їхню, і в ланцюгах відвели його у землю Єгипетську.","І коли, почекавши, побачила вона, що надія її пропала, тоді взяла іншого із левенят своїх і зробила його молодим левом.","І, зробившись молодим левом, він став ходити між левами і навчився ловити здобич, їв людей","і оскверняв удів їхніх і міста їхні спустошував; і опустіла земля і всі селища її від рикання його.","Тоді повстали на нього народи з навколишніх областей і розкинули на нього сіть свою; він упійманий був у яму їхню.","І посадили його у клітку на ланцюзі і відвели його до царя Вавилонського; відвели його у фортецю, щоб не чутний уже був голос його на горах Ізраїлевих.","Твоя мати була, як виноградна лоза, посаджена біля води; плодюча і гілляста була вона від достатку води.","І були у неї гілки міцні для скіпетрів володарів, і високо піднявся стовбур її між густими гілками; і виділялася вона висотою своєю з безліччю гілок своїх.","Але у гніві вирвана, кинута на землю, і східний вітер висушив плід її; відрізані і засохли міцні гілки її, вогонь пожер їх.","А тепер вона пересаджена у пустелю, у землю суху і спраглу.","І вийшов вогонь із стовбура гілок її, пожер плоди її і не залишилося на ній гілок міцних для скіпетра володаря. Це жалібна пісня, і залишиться для плачу."],"x":{"2":"44.2.11|46.3.3","3":"11.23.31|48.11.3","4":"11.23.33|32.22.11-12","5":"11.23.34","7":"40.3.4:6","8":"36.17.20","9":"13.36.6","12":"38.13.15"}},{"v":["У сьомому році, у п’ятому місяці, у десятий день місяця, прийшли мужі зі старійшин Ізраїлевих запитати Господа і сіли перед лицем моїм.","І було до мене слово Господнє:","сину людський! говори зі старійшинами Ізраїлевими і скажи їм: так говорить Господь Бог: ви прийшли запитати Мене? Живу Я, не дам вам відповіді, — говорить Господь Бог.","Чи хочеш судитися з ними, чи хочеш судитися, сину людський? вислови їм мерзоти батьків їхніх","і скажи їм: так говорить Господь Бог: у той день, коли Я обрав Ізраїля і, піднявши руку Мою, поклявся племені дому Якова, і відкрив Себе їм у землі Єгипетській, і, піднявши руку, сказав їм: «Я Господь Бог ваш!» —","у той день, піднявши руку Мою, Я поклявся їм вивести їх із землі Єгипетської у землю, яку Я приглянув для них, яка тече молоком і медом, красу всіх земель,","і сказав їм: відкиньте кожен мерзоти від очей ваших і не оскверняйте себе ідолами єгипетськими: Я Господь Бог ваш.","Але вони збурилися проти Мене і не хотіли слухати Мене; ніхто не відкинув мерзот від очей своїх і не залишив ідолів єгипетських. І Я сказав: виллю на них гнів Мій, виснажу на них лють Мою серед землі Єгипетської.","Але Я вчинив заради імені Мого, щоб воно не хулилося перед народами, серед яких знаходилися вони і перед очима яких Я відкрив Себе їм, щоб вивести їх із землі Єгипетської.","І Я вивів їх із землі Єгипетської і привів їх у пустелю,","і дав їм заповіді Мої, й оголосив їм Мої постанови, виконуючи які людина була б живою через них;","дав їм також суботи Мої, щоб вони були знаменням між Мною і ними, щоб знали, що Я Господь, Який освячує їх.","Але дім Ізраїлів збурився проти Мене у пустелі: за заповідями Моїми не чинили і відкинули постанови Мої, виконуючи які людина живою була б через них, і суботи Мої порушували, і Я сказав: виллю на них лють Мою у пустелі, щоб знищити їх.","Але Я вчинив заради імені Мого, щоб воно не хулилося перед народами, на очах яких Я вивів їх.","Навіть Я, піднявши руку Мою проти них у пустелі, поклявся, що не введу їх у землю, яку Я призначив, — яка тече молоком і медом, красу всіх земель, —","за те, що вони відкинули постанови Мої, і не ходили за заповідями Моїми, і порушували суботи Мої; бо серце їхнє прагнуло до ідолів їхніх.","Але око Моє пошкодувало погубити їх; і Я не знищив їх у пустелі.","І говорив Я синам їхнім у пустелі: не ходіть за правилами батьків ваших, і не дотримуйтесь настанов їхніх, і не оскверняйте себе ідолами їхніми.","Я Господь Бог ваш: за Моїми заповідями живіть, і Моїх уставів дотримуйтеся, і виконуйте їх.","І святіть суботи Мої, щоб вони були знаменням між Мною і вами, щоб ви знали, що Я Господь Бог ваш.","Але і сини збурилися проти Мене: за заповідями Моїми не чинили й уставів Моїх не дотримувалися, не виконували того, виконуючи що людина була б жива, порушували суботи Мої, — і Я сказав: виллю на них гнів Мій, виснажу над ними лють Мою у пустелі;","але Я відхилив руку Мою і вчинив заради імені Мого, щоб воно не хулилося перед народами, перед очима яких Я вивів їх.","Також, піднявши руку Мою у пустелі, Я поклявся розсіяти їх серед народів і розвіяти їх по землі","за те, що вони постанов Моїх не виконували і заповіді Мої відкинули, і порушували суботи Мої, й очі їхні поверталися до ідолів батьків їхніх.","І попустив їм настанови недобрі й постанови, від яких вони не могли бути живі,","і попустив їм осквернитися жертвоприношеннями їхніми, коли вони стали проводити через вогонь усякий перший плід утроби, щоб розорити їх, щоб знали, що Я Господь.","Тому говори дому Ізраїлевому, сину людський, і скажи їм: так говорить Господь Бог: ось чим ще хулили Мене батьки ваші, віроломно вчиняючи проти Мене:","Я привів їх у землю, яку з клятвою обіцяв дати їм, піднявши руку Мою, — а вони, виглядівши собі усякий високий пагорб і всяке гіллясте дерево, стали заколювати там жертви свої, і ставили там образливі для Мене приношення свої і запашні куріння свої, й узливали там узливання свої.","І Я говорив їм: що це за висота, куди ходите ви? тому ім’ям Бама називається вона і до цього дня.","Тому скажи дому Ізраїлевому: так говорить Господь Бог: чи не оскверняєте ви себе за прикладом батьків ваших і чи не блудодієте услід мерзотам їхнім?","Приносячи дари ваші і проводячи синів ваших через вогонь, ви оскверняєте себе всіма ідолами вашими до цього дня, і хочете запитувати Мене, доме Ізраїлів? живу Я, — говорить Господь Бог, — не дам вам відповіді.","І що приходить вам на думку, зовсім не збудеться. Ви говорите: «будемо, як язичники, як племена іноземні, служити дереву і каменю».","Живу Я, — говорить Господь Бог: рукою міцною і силою великою і виливом гніву буду панувати над вами.","І виведу вас із народів і з країн, по яких ви розсіяні, і зберу вас рукою міцною і силою великою і виливом гніву.","І приведу вас у пустелю народів, і там буду судитися із вами лицем до лиця.","Як Я судився з батьками вашими у пустелі землі Єгипетської, так буду судитися з вами, — говорить Господь Бог.","І проведу вас під жезлом і введу вас в узи завіту.","І виділю з вас заколотників і непокірливих Мені. Із землі перебування їх виведу їх, але у землю Ізраїлеву вони не ввійдуть, і пізнаєте, що Я Господь.","А ви, доме Ізраїлів, — так говорить Господь Бог, — йдіть кожен до своїх ідолів і служіть їм, якщо Мене не слухаєте, але не оскверняйте більше святого імені Мого дарами вашими й ідолами вашими,","тому що на Моїй святій горі, на горі високій Ізраїлевій, — говорить Господь Бог, — там буде служити Мені весь дім Ізраїлів, — весь, скільки є його на землі; там Я з благоволінням прийму їх, і там вимагатиму приношень ваших і начатків ваших з усіма святинями вашими.","Прийму вас, як запашне куріння, коли виведу вас із народів і зберу вас із країн, по яких ви розсіяні, і буду святитися у вас перед очима народів.","І пізнаєте, що Я Господь, коли введу вас у землю Ізраїлеву, — у землю, яку Я клявся дати батькам вашим, піднявши руку Мою.","І згадаєте там про путі ваші і про всі діла ваші, якими ви оскверняли себе, і гребуватимете самими собою за всі злодіяння ваші, які ви робили,","І пізнаєте, що Я Господь, коли буду чинити з вами заради імені Мого, не за злими вашими шляхами і вашими ділами розпусними, доме Ізраїлів, — говорить Господь Бог.","І було до мене слово Господнє:","сину людський! поверни лице твоє на шлях до полудня, і промов слово на полудень, і проречи пророцтво на ліс південного поля.","І скажи південному лісу: слухай слово Господа; так говорить Господь Бог: ось, Я запалю у тобі вогонь, і він пожере у тобі всяке дерево зелене і всяке дерево сухе; не згасне палаюче полум’я, і все буде спалено ним від півдня до півночі.","І побачить усяка плоть, що Я, Господь, запалив його, і він не згасне.","І сказав я: о, Господи Боже! вони говорять про мене: «чи не говорить він притчі?»"],"x":{"1":"36.14.1","3":"36.14.3","4":"36.22.2","5":"1.3.6:8","6":"1.3.17","7":"1.23.24|1.34.13","9":"3.14.16|31.52.5","10":"1.16.1","11":"2.18.5|17.9.29|62.10.5|65.3.12","12":"1.20.8|1.31.13|4.5.12","13":"1.16.28-29","14":"3.14.16|4.9.28","15":"3.14.30|25.94.11|75.3.11","16":"38.9.17","17":"36.5.11","18":"4.4.25","21":"37.9.11","22":"3.14.13","25":"25.80.13|70.2.9-10","26":"36.20.31","28":"0.17.8|0.22.16","29":"4.12.2","31":"36.16.21","32":"32.44.17|38.4.13","35":"31.1.18","36":"3.14.22","37":"63.4.21","38":"50.25.31-32","39":"31.29.23","40":"31.27.13|48.8.22|48.14.16","41":"62.12.1|62.15.16|67.4.18","43":"36.6.9|36.16.61","46":"40.7.15","47":"32.11.16|32.17.27|36.28.18","48":"32.7.20","49":"36.17.2"}},{"v":["І було до мене слово Господнє:","сину людський! поверни лице твоє до Єрусалима і промов слово на святилища, і виречи пророцтво на землю Ізраїлеву,","і скажи землі Ізраїлевій: так говорить Господь Бог: ось, Я — на тебе, і витягну меч Мій з піхов його і знищу в тебе праведного і нечестивого.","А для того, щоб знищити у тебе праведного і нечестивого, меч Мій з піхов своїх піде на всяку плоть від півдня до півночі.","І пізнає всяка плоть, що Я, Господь, витяг меч Мій з піхов його, і він уже не повернеться.","Ти ж, сину людський, стогни, скрушуючи стегна твої, і у го́рі стогни перед очима їхніми.","І коли скажуть тобі: «чого ти стогнеш?», скажи: «від чутки, що йде», — і розтане всяке серце, і всі руки опустяться, і всякий дух знеможе, й усі коліна затремтять, як вода. Ось, це прийде і збудеться, — говорить Господь Бог.","І було до мене слово Господнє:","сину людський! виречи пророцтво і скажи: так говорить Господь Бог: скажи: меч, меч нагострений і вичищений;","нагострений для того, щоб більше заколоти; вичищений, щоб блищав, як блискавка. Чи радіти нам, що жезл сина Мого зневажає всяке дерево?","Я дав його вичистити, щоб узяти у руку; уже нагострений цей меч і вичищений, щоб віддати його у руку вбивці.","Стогни і ридай, сину людський, бо він — на народ Мій, на всіх князів Ізраїля; вони віддані будуть під меч з народом Моїм; тому вдаряй себе по стегнах.","Бо він уже випробуваний. І що, коли він зневажає і жезл? цей не встоїть, — говорить Господь Бог.","Ти ж, сину людський, пророкуй і вдаряй рукою об руку; і подвоїться меч і потроїться, меч на тих, яких уражають, меч на поразку великого, який проникає в нутрощі осель їх.","Щоб розтанули серця і щоб полеглих було більше, Я біля всіх воріт їх поставлю грізний меч, о, горе! блискучий, як блискавка, нагострений для заколення.","Зберися і йди праворуч або йди ліворуч, куди б не обернулося лице твоє.","І Я буду плескати у долоні й угамую гнів Мій; Я, Господь, сказав.","І було до мене слово Господнє:","і ти, сину людський, уяви собі дві дороги, по яких слід іти мечу царя Вавилонського, — обидві вони повинні виходити з однієї землі; і накресли руку, накресли на початку доріг до міст.","Уяви дорогу, по якій меч ішов би у Равву синів Аммонових і в Юдею, в укріплений Єрусалим;","тому що цар Вавилонський зупинився на роздоріжжі, на початку двох доріг, для ворожіння: трясе стріли, запитує терафимів, розглядає печінку.","У правій руці у нього жереб: «у Єрусалим», де слід поставити тарани, відкрити для побоїща вуста, піднести голос для воєнного крику, підвести тарани до воріт, насипати вал, побудувати облогові вежі.","Це ворожіння здалося в очах їх неправдивим; але оскільки вони клялися клятвою, то він, згадавши про таке їхнє віроломство, вирішив узяти його.","Тому так говорить Господь Бог: оскільки ви самі приводите на пам’ять беззаконня ваше, роблячи явними злочини ваші, виставляючи на вид гріхи ваші в усіх ділах ваших, і самі приводите це на пам’ять, то ви будете взяті руками.","І ти, недостойний, злочинний вождь Ізраїля, день якого настав нині, коли нечестю його буде покладено кінець!","Так говорить Господь Бог: зніми із себе діадему і поклади вінець; цього вже не буде; принижене піднесеться і високе принизиться.","Скину, скину, скину і його не буде, доки не прийде Той, Кому належить він, і Я дам Йому.","І ти, сину людський, проречи пророцтво і скажи: так говорить Господь Бог про синів Аммона і про ганьбу їх; і скажи: меч, меч оголений для заколення, вичищений для знищення, щоб блищав, як блискавка,","щоб, тоді як представляють тобі пусті видіння і неправдиво ворожать тобі, і тебе доклав до обезголовлених нечестивців, день яких настав, коли нечестю їх буде покладений кінець.","Чи повернути його у піхви його? — на місці, де ти створений, на землі походження твого буду судити тебе:","і виллю на тебе обурення Моє, дихну на тебе вогнем люті Моєї і віддам тебе до рук людей лютих, досвідчених у вбивстві.","Ти будеш поживою вогню, кров твоя залишиться на землі; не будуть і згадувати про тебе; бо Я, Господь, сказав це."],"x":{"2":"36.20.46","3":"36.20.47","7":"36.7.17","9":"36.33.27|32.47.6","12":"36.6.11","17":"25.2.4|26.1.26|36.5.17","21":"41.1.14|31.19.3","22":"36.23.24","26":"11.25.27","27":"48.9.9|76.19.16","28":"32.49.2","29":"25.36.13|36.35.5"}},{"v":["І було до мене слово Господнє:","і ти, сину людський, чи хочеш судити, судити місто крови? вислови йому всі мерзоти його.","І скажи: так говорить Господь Бог: о, місто, що проливаєш кров серед себе, щоб настав час твій, і що робиш у себе ідолів, щоб оскверняти себе!","Кров’ю, яку ти пролило, ти зробило себе винним, й ідолами, яких ти наробило, ти осквернило себе, і наблизило дні твої і досягло часу твого. За це віддам тебе на посміяння народам, на наругу всім землям.","Близькі й далекі від тебе будуть насміхатися з тебе, що осквернило ім’я своє, прославилося шаленством.","Ось ті, що начальствують у Ізраїля, кожен мірою сил своїх, були у тебе, щоб проливати кров.","У тебе батька і матір лихословлять, прибульцеві чинять образу посеред тебе, сироту і вдову пригноблюють у тебе.","Святинь Моїх ти не поважаєш і суботи Мої порушуєш.","Наклепники знаходяться у тобі, щоб проливати кров, і на горах їдять у тебе ідоложертовне, посеред тебе роблять мерзоти.","Наготу батька відкривають у тебе, дружину під час очищення нечистот її ґвалтують у тебе.","Хтось робить мерзоти з дружиною ближнього свого, інший осквернює невістку свою, ще інший ґвалтує сестру свою, дочку батька свого.","Хабарі беруть у тебе, щоб проливати кров; ти береш ріст і лихву і насильством вимагаєш користь у ближнього твого, а Мене забуло, — говорить Господь Бог.","І ось, Я сплеснув руками Моїми за користолюбство твоє, яке виявляється у тебе, і за кровопролиття, що відбувається посеред тебе.","Чи устоїть серце твоє, чи будуть тверді руки твої у ті дні, у які буду діяти проти тебе? Я, Господь, сказав і зроблю.","І розсію тебе серед народів, і розвію тебе по землях, і покладу кінець мерзотам твоїм посеред тебе.","І зробиш сам себе зневаженим перед очима народів, і пізнаєш, що Я Господь.","І було до мене слово Господнє:","сину людський! дім Ізраїлів зробився у Мене окалиною; усі вони — олово, мідь і залізо і свинець у горнилі, зробилися, як окалина срібла.","Тому так говорить Господь Бог: оскільки усі ви зробилися окалиною, за те ось, Я зберу вас у Єрусалим.","Як у горнило кладуть разом срібло, і мідь, і залізо, і свинець, і олово, щоб роздмухати на них вогонь і розплавити; так Я у гніві Моєму й у люті Моїй зберу, і покладу, і розплавлю вас.","Зберу вас і дихну на вас вогнем обурення Мого, і розплавитеся серед нього.","Як срібло розплавляється у горнилі, так розплавитеся і ви серед нього, і пізнаєте, що Я, Господь, вилив лють Мою на вас.","І було до мене слово Господнє:","сину людський! скажи йому: ти — земля неочищена, не зрошувана дощем у день гніву!","Змова пророків її серед неї — як лев, що рикає, терзає здобич; з’їдають душі, оббирають майно і коштовності, і множать кількість удів.","Священики її порушують закон Мій і оскверняють святині Мої, не відокремлюють святого від несвятого і не вказують різниці між чистим і нечистим, і від субот Моїх вони закрили очі свої, і Я принижений у них.","Князі у неї, як вовки, які викрадають здобич; проливають кров, гублять душі, щоб придбати користь.","А пророки її все замазують брудом, бачать пусте і пророкують їм неправдиве, говорячи: «так говорить Господь Бог», тоді як не говорив Господь.","А в народі гнітять одне одного, грабують і пригноблюють бідного й убогого, і прибульця пригноблюють несправедливо.","Шукав Я у них людину, яка поставила б стіну і стала б переді Мною у проломі за цю землю, щоб Я не погубив її, але не знайшов.","Отже, виллю на них обурення Моє, вогнем люті Моєї знищу їх, поведінку їхню поверну їм на голову, — говорить Господь Бог."],"x":{"2":"36.20.4","4":"11.21.16","6":"43.3.1","7":"25.93.6","11":"36.33.26","12":"2.25.36|26.28.8","14":"36.17.24","15":"36.12.15","18":"32.6.28","21":"4.4.24|31.30.27|44.1.6","22":"48.13.9|49.3.3|49.4.1","24":"75.6.7","25":"31.1.23|43.3.2|46.3.3|50.23.14","26":"43.3.11|46.3.4|36.44.23","27":"43.3.10|46.3.3","28":"36.13.6","29":"32.3.5|32.9.3|1.22.21","30":"36.13.5","31":"36.7.4:8"}},{"v":["І було до мене слово Господнє:","сину людський! були дві жінки, дочки однієї матері,","і блудили вони в Єгипті, блудили у своїй молодості; там зім’яті груди їхні, і там розбестили дівочі соски їхні.","Імена їх: старшої — Огола, а сестри її — Оголива. І були вони Моїми, і народжували синів і дочок; й іменувалися — Огола Самарією, а Оголива Єрусалимом.","І стала Огола блудити від Мене і приліплялася до своїх коханців, до ассиріян, до сусідів своїх,","до тих, що вдягалися у тканини яхонтового кольору, до областеначальників і градоправителів, до всіх красивих юнаків, вершників, що їздять на конях;","і розсипала блудодіяння свої з усіма добірними із синів Ассура, і осквернила себе всіма ідолами тих, до кого б не приліплялася:","не переставала блудити і з єгиптянами, тому що вони з нею спали у молодості її і розбещували дівочі соски її, і виливали на неї похіть свою.","За те Я і віддав її до рук коханців її, до рук синів Ассура, до яких вона приліплялася.","Вони відкрили наготу її, взяли синів її і дочок її, а її вбили мечем. І вона зробилася ганьбою між жінками, коли звершили над нею страту.","Сестра її, Оголива, бачила це, і була ще розбещенішою у коханні своєму, і блуд її перевершив блуд сестри її.","Вона приліпилася до синів Ассурових, до областеначальників і градоправителів, сусідів її, пишно одягнених, до вершників, що їздять на конях, до всіх добірних юнаків.","І Я бачив, що вона осквернила себе, і що в обох їх одна дорога.","Але ця ще примножила блудодіяння свої, тому що, побачивши вирізаних на стіні чоловіків, фарбами намальовані зображення халдеїв,","підперезаних по стегнах своїх поясом, з розкішними на голові їх пов’язками, що мають вигляд воєначальників, схожих на синів Вавилона, батьківщина яких земля Халдейська,","вона закохалася у них з одного погляду очей своїх і послала до них у Халдею послів.","І прийшли до неї сини Вавилона на любовне ложе, й осквернили її блудодійством своїм, і вона осквернила себе ними; і відвернулася від них душа її.","Коли ж вона явно віддалася блудодіянням своїм і відкрила наготу свою, тоді і від неї відвернулася душа Моя, як відвернулася душа Моя від сестри її.","І вона множила блудодіяння свої, згадуючи дні молодости своєї, коли блудила у землі Єгипетській;","і приліпилася до коханців своїх, у яких плоть — плоть осляча, і похіть, як у жеребців.","Так ти згадала розпусту молодости твоєї, коли єгиптяни стискали соски твої заради дівочих грудей твоїх.","Тому, Оголиво, так говорить Господь Бог: ось, Я підбурю проти тебе коханців твоїх, від яких відвернулася душа твоя, і приведу їх проти тебе з усіх боків:","синів Вавилона і всіх халдеїв, з Пехода, із Шоа і Коа, і з ними всіх синів Ассура, красивих юнаків, областеначальників і градоправителів, сановних та іменитих, усіх майстерних наїзників.","І прийдуть на тебе зі зброєю, з конями і колісницями і з безліччю народу, й обступлять тебе навколо у латах, зі щитами й у шоломах, і віддам їм тебе на суд, і будуть судити тебе своїм судом.","І оберну ревність Мою проти тебе, і вчинять з тобою люто: відріжуть у тебе ніс і вуха, а інше твоє від меча упаде; візьмуть синів твоїх і дочок твоїх, а інше твоє вогнем буде пожерте;","і знімуть з тебе одяг твій, візьмуть убрання твоє.","І покладу кінець розпусті твоїй і блуду твоєму, принесеному із землі Єгипетської, і не будеш звертати на них очей твоїх, і про Єгипет уже не згадаєш.","Бо так говорить Господь Бог: ось, Я віддаю тебе до рук тих, кого ти зненавиділа, до рук тих, від кого відвернулася душа твоя.","І вчинять з тобою жорстоко, і візьмуть у тебе все, набуте працею, і залишать тебе нагою і непокритою, і відкрита буде соромітна нагота твоя, і розпуста твоя, і блудодійство твоє.","Це буде зроблено з тобою за блудодійство твоє з народами, ідолами яких ти осквернила себе.","Ти ходила дорогою сестри твоєї; за те і дам у руку тобі чашу її.","Так говорить Господь Бог: ти будеш пити чашу сестри твоєї, глибоку і широку, і будеш піддана осміянню і ганьбі, за величезної місткости її.","Сп’янінням і гіркотою будеш сповнена: чаша жаху і спустошення — чаша сестри твоєї, Самарії!","І вип’єш її, і осушиш, і черепки її оближеш, і груди твої пошматуєш: бо Я сказав це, — говорить Господь Бог.","Тому так говорить Господь Бог: оскільки ти забула Мене і відвернулася від Мене, то і терпи за беззаконня твоє і за блудодійство твоє.","І сказав мені Господь: сину людський! чи хочеш судити Оголу й Оголиву? вислови їм мерзоти їх;","бо вони перелюбствували, і кров на руках їх, і з ідолами своїми перелюбствували, і синів своїх, яких народили Мені, через вогонь проводили в їжу їм.","Ще ось що вони робили Мені: оскверняли святилище Моє у той самий день, і порушували суботи Мої;","тому що, коли вони заколювали дітей своїх для ідолів своїх, у той самий день приходили у святилище Моє, щоб оскверняти його: ось як чинили вони у домі Моєму!","Крім цього, посилали за людьми, які приходили здалеку; до них відправляли послів, і ось, вони приходили, і ти для них умивалася, підмальовувала очі твої і прикрашалася убраннями,","і сідали на чудове ложе, перед яким приготований був стіл і на якому пропонувала ти запашні куріння Мої і єлей Мій.","І лунав голос народу, який радів у неї, і до людей з натовпу народного вводилися п’яниці з пустелі; і вони покладали на руки їхні зап’ястя і на голови їхні красиві вінки.","Тоді сказав Я про підтоптану в перелюбстві: тепер закінчаться блудодіяння її разом з нею.","Але приходили до неї, як приходять до жінки блудниці, так приходили до Оголи й Оголиви, до розпусних жінок.","Але мужі праведні будуть судити їх; вони будуть судити їх судом перелюбниць і судом тих, що проливають кров, тому що вони перелюбниці, й у них кров на руках.","Бо так сказав Господь Бог: скликати на них зібрання і віддати їх на озлоблення і грабунок.","І зібрання поб’є їх камінням, і порубає їх мечами своїми, й уб’є синів їх і дочок їх, і доми їх спалить вогнем.","Так покладу кінець розпусті на цій землі, й усі жінки приймуть урок, і не будуть робити соромітних діл подібно до вас;","і покладуть на вас вашу розпусту, і понесете покарання за гріхи з ідолами вашими, і пізнаєте, що Я Господь Бог."],"x":{"2":"32.3.7-8","3":"25.72.27|38.1.2|44.3.4|36.16.26","4":"36.16.46","5":"38.2.2|38.5.3|11.15.19","7":"36.16.15","8":"36.16.26","10":"36.16.38-39","11":"36.16.51","14":"36.8.3","17":"36.23.22","20":"32.5.8|32.8.12|36.16.26","23":"36.23.12","24":"36.21.22","26":"36.16.39","29":"32.13.22|36.16.37","31":"25.74.9|32.25.15","35":"32.2.32|32.3.21|38.2.13","37":"32.7.31|36.16.20|36.20.26","39":"31.1.11-12","44":"36.16.30","45":"36.16.38|31.1.15","47":"36.16.40","49":"36.7.27|36.26.6|36.39.26"}},{"v":["І було до мене слово Господнє у дев’ятому році, у десятому місяці, у десятий день місяця:","сину людський! запиши собі ім’я цього дня, цього самого дня: у цей самий день цар Вавилонський підступить до Єрусалима.","І промов на бунтівний дім притчу, і скажи їм: так говорить Господь Бог: постав казан, постав і налий у нього води;","склади у нього шматки м’яса, всі кращі шматки, стегна і плечі, і наповни добірними кістками;","добірних овець візьми, і розпали під ним кістки, і кип’яти до того, щоб і кістки розварилися у ньому.","Тому так говорить Господь Бог: горе місту крови! горе казану, в якому є накип і з якого накип його не сходить! шматок за шматком його викидайте з нього, не вибираючи за жеребом.","Бо кров його посеред нього; він залишив її на голій скелі; не на землю проливав її, де вона могла б вкритися пилом.","Щоб збудити гнів для звершення помсти, Я залишив кров його на голій скелі, щоб вона не сховалася.","Тому так говорить Господь Бог: горе місту крови! і Я розкладу велике багаття.","Додай дров, розведи вогонь, вивари м’ясо; нехай усе загусне, і кістки перегорять.","І коли казан буде порожній, постав його на вугілля, щоб він розгорівся, і щоб мідь його розжарилася, і розплавилася у ньому нечистота його, і весь накип його зник.","Праця буде важкою; але великий накип його не зійде з нього; й у вогні залишиться на ньому накип його.","У нечистоті твоїй така мерзота, що, скільки Я не чищу тебе, ти все нечистий; від нечистоти твоєї ти і надалі не очистишся, доки люті Моєї Я не вгамую на тобі.","Я Господь, Я говорю: це прийде і Я зроблю; не скасую і не пощаджу, і не помилую. За путями твоїми і за ділами твоїми будуть судити тебе, — говорить Господь Бог.","І було до мене слово Господнє:","сину людський! ось, Я візьму в тебе виразкою утіху очей твоїх; але ти не ремствуй і не плач, і сльози нехай не виступають у тебе;","зітхай у безмовності, плачу за померлим не звершуй; але обв’язуй себе пов’язкою і взувай ноги твої у взуття твоє, і бороди́ не закривай, і хліба від чужих не їж.","І після того, як говорив я зранку слово до народу, ввечері померла дружина моя, і наступного дня я зробив так, як наказано було мені.","І сказав мені народ: чи не скажеш нам, яке для нас значення у тому, що ти робиш?","І сказав я їм: до мене було слово Господнє:","скажи дому Ізраїлевому: так говорить Господь Бог: ось, Я віддам на наругу святилище Моє, опору сили вашої, утіху очей ваших і розраду душі вашої, а сини ваші і дочки ваші, яких ви залишили, упадуть від меча.","І ви будете робити те саме, що робив я; бороди́ не будете закривати, і хліба від чужих не будете їсти;","і пов’язки ваші будуть на головах ваших, і взуття ваше на ногах ваших; не будете ремствувати і плакати, але будете танути від гріхів ваших і зітхати одне перед одним.","І буде для вас Єзекиїль знаменням: усе, що він робив, і ви будете робити; і коли це збудеться, пізнаєте, що Я Господь Бог.","А що до тебе, сину людський, то у той день, коли Я візьму у них прикрасу слави їх, утіху очей їх і розраду душі їх, синів їх і дочок їх, —","у той день прийде до тебе той, хто спасся звідти, щоб подати звістку у вуха твої.","У той день при цьому, який спасся, відкриються вуста твої, і ти будеш говорити, і не залишишся вже безмовним, і будеш знаменням для них, і пізнають, що Я Господь."],"x":{"2":"32.22.30|11.25.1","4":"43.3.3","6":"44.3.1|45.2.12","7":"0.4.10|36.26.4|25.78.13","9":"44.3.1","13":"36.5.13|36.16.42","16":"26.31.10|30.26.16|63.7.29-30","17":"4.26.14|38.9.4|36.24.22","22":"32.16.7|36.24.17","23":"36.24.22","24":"36.12.6","25":"25.143.12","26":"36.33.21","27":"36.15.7|36.24.24|36.29.21|40.5.13"}},{"v":["І було до мене слово Господнє:","сину людський! поверни лице твоє до синів Аммонових і проречи на них пророцтво,","і скажи синам Аммоновим: слухайте слово Господа Бога: так говорить Господь Бог: за те, що ти про святилище Моє говориш: «а! а!», тому що воно зганьблене, — і про землю Ізраїлеву, тому що вона спустошена, і про дім Іудин, тому що вони пішли у полон, —","за те ось, Я віддам тебе у спадщину синам сходу, і побудують у тебе кошари свої, і поставлять у тебе намети свої, і будуть їсти плоди твої і пити молоко твоє.","Я зроблю Равву стійлом для верблюдів, і синів Аммонових — пастухами овець, і пізнаєте, що Я Господь.","Бо так говорить Господь Бог: за те, що ти плескав у долоні й тупав ногою, і з усім презирством до землі Ізраїлевої душевно радів, —","за те ось, Я простягну руку Мою на тебе і віддам тебе на розкрадання народам, і знищу тебе з числа народів, і згладжу тебе з числа земель; скрушу тебе, і пізнаєш, що Я Господь.","Так говорить Господь Бог: за те, що Моав і Сеїр говорять: «ось і дім Іудин, як усі народи!»,","за те ось, Я, починаючи від міст, від усіх прикордонних міст його, краси землі, від Беф-Ієшимофа, Ваалмеона і Киріафаїма, відкрию бік Моава","для синів сходу і віддам його у спадщину їм, разом із синами Аммоновими, щоб сини Аммона не згадувалися більше серед народів.","І над Моавом учиню суд, і пізнають, що Я Господь.","Так говорить Господь Бог: за те, що Едом жорстоко мстився дому Іудиному і тяжко згрішив, звершуючи над ним помсту,","за те, так говорить Господь Бог: простягну руку Мою на Едома і знищу у нього людей і худобу, і зроблю його пустелею; від Фемана до Дедана усі впадуть від меча.","І звершу помсту Мою над Едомом рукою народу Мого, Ізраїля; і вони будуть діяти в Ідумеї за Моїм гнівом і Моїм обуренням, і пізнають помсту Мою, — говорить Господь Бог.","Так говорить Господь Бог: за те, що филистимляни вчинили мстиво і мстилися з презирством у душі, на загибель, з вічної ворожости,","за те, так говорить Господь Бог: ось, Я простягну руку Мою на филистимлян, і знищу критян, і знищу залишок їх на березі моря;","і звершу над ними велику помсту покараннями лютими; і пізнають, що Я Господь, коли звершу над ними Мою помсту."],"x":{"2":"32.49.1","3":"25.34.21|36.26.2|36.36.2","5":"36.24.27|36.26.6","7":"36.7.27|36.13.23","8":"31.15.1|32.48.1|36.35.2","9":"32.48.1|40.2.2","12":"32.49.7|41.1.8","13":"40.1.12","15":"31.14.2|32.47.1-2"}},{"v":["В одинадцятому році, у перший день першого місяця, було до мене слово Господнє:","сину людський! за те, що Тир говорить про Єрусалим: «а! а! він розбитий — врата народів; він звертається до мене; наповнюся; він спустошений», —","за те, так говорить Господь Бог: ось, Я — на тебе, Тире, і підніму на тебе багато народів, як море піднімає хвилі свої.","І розіб’ють стіни Тира і зруйнують вежі його; і вимету з нього порох його і зроблю його голою скелею.","Місцем для розстеляння тенет буде він серед моря; бо Я сказав це, — говорить Господь Бог: і буде він на розкрадання народам.","А дочки його, які на землі, будуть убиті мечем, і пізнають, що Я Господь.","Бо так говорить Господь Бог: ось, Я приведу проти Тира від півночі Навуходоносора, царя Вавилонського, царя царів, з кіньми і з колісницями, і з вершниками, і з військом, і з численним народом.","Дочок твоїх на землі він поб’є мечем і збудує проти тебе облогові вежі, і насипле проти тебе вал, і поставить проти тебе щити;","і до стін твоїх присуне стінопробивні машини і вежі твої зруйнує сокирами своїми.","Від безлічі коней його покриє тебе пил, від шуму вершників і коліс і колісниць потрясуться стіни твої, коли він буде входити у ворота твої, як входять у розбите місто.","Копитами коней своїх він витопче усі вулиці твої, народ твій поб’є мечем і пам’ятники могутности твоєї повалить на землю.","І розграбують багатство твоє, і розкрадуть товари твої, і зруйнують стіни твої, і розіб’ють красиві доми твої, і камені твої і дерева твої, і землю твою кинуть у воду.","І припиню шум пісень твоїх, і звук цитр твоїх уже не буде чутний.","І зроблю тебе голою скелею, будеш місцем для розстеляння тенет; не будеш знову побудований: бо Я, Господь, сказав це, — говорить Господь Бог.","Так говорить Господь Бог Тиру: від шуму падіння твого, від стогону поранених, коли відбудеться серед тебе побиття, чи не здригнуться острови?","І зійдуть усі князі моря з престолів своїх, і складуть із себе мантії свої, і знімуть із себе візерунчастий одяг свій, одягнуться у трепет, сядуть на землю, і щохвилини будуть здригатись і дивуватися щодо тебе.","І здіймуть плач по тобі і скажуть тобі: як загинуло ти, населене мореплавцями, місто знамените, яке було сильним на морі, саме́ і жителі його, які наводили страх на всіх мешканців його!","Нині, у день падіння твого, здригнулися острови; острови на морі приведені у сум’яття загибеллю твоєю.","Бо так говорить Господь Бог: коли Я зроблю тебе містом спустілим, подібним до міст ненаселених, коли підніму на тебе безодню, і покриють тебе великі води;","тоді зведу тебе з тими, що відходять у могилу до народу, який жив давно, і розміщу тебе у пеклі землі, у пустелях вічних, з тими, що зійшли у могилу, щоб ти не було більше населене; і явлю Я славу на землі живих.","Жахом зроблю тебе, і не буде тебе, і будуть шукати тебе, але вже не знайдуть тебе повіки, — говорить Господь Бог."],"x":{"2":"31.23.1|32.47.4","3":"31.8.7","6":"36.25.7","7":"36.28.7|37.2.37","9":"36.4.2|36.21.22","13":"31.24.8|32.7.34","14":"36.26.4","15":"36.24.21","16":"76.18.9","17":"38.9.13","20":"36.28.8|36.31.14|25.142.7"}},{"v":["І було до мене слово Господнє:","і ти, сину людський, здійми плач за Тиром","і скажи Тиру, що оселився на виступах біля моря, що торгує з народами на багатьох островах: так говорить Господь Бог: Тире! ти говориш: «я досконалість краси!»","Межі твої у серці морів; будівельники твої довершили красу твою:","із сенирських кипарисів зробили всі помости твої; брали з Ливану кедр, щоб зробити на тобі щогли;","з дубів васанських робили весла твої; лави твої робили з букового дерева, з оправою зі слонової кістки з островів Киттимських;","візерунчасті полотна з Єгипту використовувалися на вітрила твої і служили прапором; блакитного і пурпурового кольору тканини з островів Елиси були покривалом твоїм.","Жителі Сидона й Арвада були у тебе веслярами; свої знавці були у тебе, Тире; вони були у тебе керманичами.","Старші з Гевала і знавці його були у тебе, щоб зашпаровувати пробоїни твої. Усякі морські кораблі і корабельники їх знаходилися у тебе для ведення торгівлі твоєї.","Перс і лідіянин і лівієць знаходилися у війську твоєму і були у тебе ратниками, вішали на тебе щит і шолом; вони надавали тобі велич.","Сини Арвада з власним твоїм військом стояли навколо на стінах твоїх, і гамадими були на вежах твоїх; навколо по стінах твоїх вони вішали сагайдаки свої; вони довершували красу твою.","Фарсис, торговець твій, за безліччю всякого багатства, платив за товари твої сріблом, залізом, свинцем і оловом.","Іаван, Фувал і Мешех торгували з тобою, вимінюючи товари твої на душі людські і мідний посуд.","Із дому Фогарма за товари твої доставляли тобі коней і стройових коней і ослів.","Сини Дедана торгували з тобою; багато островів робили з тобою обмін, на сплату тобі доставляли слонову кістку і чорне дерево.","Через велике торговельне виробництво твоє торгували з тобою арамеяни; за товари твої вони платили карбункулами, тканинами пурпуровими, візерунчастими, і висонами, і коралами, і рубінами.","Юдея і земля Ізраїлева торгували з тобою; за товар твій платили пшеницею миннифською і солодощами, і медом, і оливою, і бальзамом.","Дамаск, через велике торгове виробництво твоє, через достаток усякого багатства, торгував з тобою вином хелбонським і білою вовною.","Дан та Іаван з Узала платили тобі за товари твої виробленим залізом; касія і запашна тростина йшли на обмін тобі.","Дедан торгував з тобою дорогоцінними попонами для верхової їзди.","Аравія і всі князі кидарські робили обмін з тобою: ягнят і баранів і козлів обмінювали тобі.","Купці із Сави і Раєми торгували з тобою всякими найкращими пахощами і всяким дорогим камінням, і золотом платили за товари твої.","Харан і Хане й Еден, купці савейські, Ассур і Хилмад торгували з тобою.","Вони торгували з тобою дорогоцінними одежами, шовковими і візерунчастими тканинами, які вони привозили на твої ринки у дорогих ящиках, зроблених з кедра і добре упакованих.","Фарсиські кораблі були твоїми караванами у твоїй торгівлі, і ти зробився багатим і дуже славним на морях.","Веслярі твої завели тебе у великі води; східний вітер розбив тебе серед морів.","Багатство твоє і товари твої, усі склади твої, корабельники твої і керманичі твої, які зашпаровували пробоїни твої і розпоряджалися торгівлею твоєю, і всі ратники твої, які у тебе були, і вся безліч народу твого, у день падіння твого упаде у серце морів.","Від крику керманичів твоїх здригнуться околиці.","І з кораблів своїх зійдуть усі веслярі, корабельники, усі керманичі моря, і стануть на землю;","і заридають за тобою гучним голосом, і гірко застогнуть, посипавши попелом голови свої і валяючись у поросі;","і обстрижуть за тобою волосся догола, й опережуться веретищами, і заплачуть за тобою від душевної скорботи гірким плачем;","і у смутку своєму піднімуть жалібну пісню про тебе, і так заридають за тобою: «хто як Тир, так зруйнований посередині моря!","Коли приходили з морів товари твої, ти насичував багато народів; безліччю багатства твого і торгівлею твоєю збагачував царів землі.","А коли ти розбитий морями у безодні вод, товари твої і все, що юрмилося у тобі, упало.","Усі мешканці островів жахнулися за тебе, і царі їх здригнулися, змінилися у лицях.","Торговці інших народів свиснули про тебе; ти зробився жахом, — і не буде тебе повіки»."],"x":{"2":"31.23.1|40.1.9","3":"36.28.12","4":"36.28.2","5":"4.3.9","6":"31.2.13|0.10.4:15|3.24.24","7":"0.10.4","8":"0.10.15:18","9":"10.5.18|25.82.8","10":"0.10.13|8.31.9|32.46.9","13":"0.10.2","15":"32.25.23","21":"0.25.13|32.2.10","22":"0.10.7","27":"76.18.17","30":"76.18.9","31":"32.16.6|32.48.37","35":"76.18.11"}},{"v":["І було до мене слово Господнє:","сину людський! скажи начальнику у Тирі: так говорить Господь Бог: за те, що піднеслося серце твоє і ти говориш: «я бог, сиджу на сідалищі Божому, у серці морів», і будучи людиною, а не Богом, ставиш розум твій нарівні з розумом Божим, —","ось, ти премудріший за Даниїла, немає таємниці, прихованої від тебе;","твоєю мудрістю і твоїм розумом ти придбав собі багатство й у скарбниці твої зібрав золото і срібло;","великою мудрістю твоєю, за допомогою торгівлі твоєї, ти примножив багатство твоє, і розум твій загордився багатством твоїм, —","за те так говорить Господь Бог: оскільки ти розум твій ставиш нарівні з розумом Божим,","ось, Я наведу на тебе іноземців, найлютіших з народів, і вони оголять мечі свої проти краси твоєї мудрости і затьмарять блиск твій;","зведуть тебе у могилу, і помреш у серці морів смертю вбитих.","Чи скажеш тоді перед твоїм убивцею: «я бог», тоді як у руці того, хто уражає тебе, ти будеш людина, а не бог?","Ти помреш від руки іноземців смертю необрізаних; бо Я сказав це, — говорить Господь Бог.","І було до мене слово Господнє:","сину людський! плач за царем Тирським і скажи йому: так говорить Господь Бог: ти печатка досконалости, повнота мудрости і вінець краси.","Ти знаходився в Едемі, у саду Божому; твій одяг був прикрашений усяким коштовним камінням; рубін, топаз і алмаз, хризоліт, онікс, яспис, сапфір, карбункул і смарагд і золото, все, майстерно посаджене у тебе у гніздах і нанизане на тебе, приготоване було в день створення твого.","Ти був помазаним херувимом, щоб осіняти, і Я поставив тебе на те; ти був на святій горі Божій, ходив серед вогнистих каменів.","Ти довершеним був на путях твоїх від дня створення твого, доки не знайшлося в тобі беззаконня.","Від великого обсягу торгівлі твоєї внутрішнє твоє наповнилося неправдою, і ти згрішив; і Я скинув тебе, як нечистого, з гори Божої, вигнав тебе херувим, який осіняє, із середовища вогнистих каменів.","Від краси твоєї загордилося серце твоє, через марнославство твоє ти погубив мудрість твою; за те Я повалю тебе на землю, перед царями віддам тебе на ганьбу.","Безліччю беззаконь твоїх у неправедній торгівлі твоїй ти осквернив святилища твої; і Я виведу із середовища твого вогонь, який і пожере тебе: і Я перетворю тебе на попіл на землі перед очима всіх, що бачать тебе.","Усі, що знали тебе серед народів, здивуються щодо тебе; ти зробишся жахом, і не буде тебе повіки.","І було до мене слово Господнє:","сину людський! поверни лице твоє до Сидона і виречи на нього пророцтво,","і скажи: ось, Я — на тебе, Сидоне, і прославлюся серед тебе, і пізнають, що Я Господь, коли вчиню суд над ним і явлю у ньому святість Мою;","і пошлю на нього моровицю і кровопролиття на вулиці його, і впадуть посеред нього убиті мечем, який пожирає його звідусюди; і пізнають, що Я Господь.","І не буде він надалі для дому Ізраїлевого колючим терням і бур’яном, який завдає болю, який більше за всіх сусідів бажає йому зла, і пізнають, що Я Господь Бог.","Так говорить Господь Бог: коли Я зберу дім Ізраїлів з народів, між якими вони розсіяні, і явлю на них святість Мою перед очима племен, і вони будуть жити на землі своїй, яку Я дав рабу Моєму Якову:","тоді вони будуть жити на ній безпечно, і побудують доми, і насадять виноградники, і будуть жити у безпеці, тому що Я вчиню суд над усіма, злозичливцями навколо них, і пізнають, що Я Господь Бог їх."],"x":{"2":"37.5.20|54.12.22","3":"37.4.5","6":"36.28.2","7":"36.26.7|36.30.11","8":"36.26.20|36.31.16:18","12":"36.27.3","13":"36.31.8|76.17.4","17":"63.4.9","18":"24.22.20|36.20.47","19":"36.27.36","21":"31.23.4:12","22":"1.14.18|25.45.11|36.26.6","24":"3.33.55","25":"2.11.44"}},{"v":["У десятому році, у десятому місяці, у дванадцятий день місяця, було до мене слово Господнє:","сину людський! оберни лице твоє до фараона, царя Єгипетського, і виречи пророцтво на нього і на весь Єгипет.","Говори і скажи: так говорить Господь Бог: ось, Я — на тебе, фараоне, царю Єгипетський, великий крокодиле, що, лежачи серед рік своїх, говориш: «моя ріка, і я створив її для себе».","Але Я вкладу гак у щелепи твої і до луски твоєї приліплю риб з рік твоїх, і витягну тебе з рік твоїх з усією рибою рік твоїх, що прилипла до луски твоєї;","і кину тебе у пустелі, тебе і всю рибу з рік твоїх, ти впадеш на відкрите поле, не приберуть і не підберуть тебе; віддам тебе на поживу звірам земним і птахам небесним.","І пізнають усі мешканці Єгипту, що Я Господь; тому що вони дому Ізраїлевому були підпорою з тростини.","Коли вони вхопилися за тебе рукою, ти розщепився і поколов їм усе плече; і коли вони сперлися на тебе, ти зламався і поранив усі стегна їм.","Тому так говорить Господь Бог: ось, Я наведу на тебе меч, і знищу у тебе людей і худобу.","І зробиться земля Єгипетська пустелею і степом; і пізнають, що Я Господь. Оскільки він говорить: «моя ріка, і я створив її»;","то ось, Я — на ріки твої, і зроблю землю Єгипетську пустелею з пустель від Мигдола до Сиєни, до самої межі Ефіопії.","Не буде проходити по ній нога людська, і нога худоби не буде проходити по ній, і не будуть жити на ній сорок років.","І зроблю землю Єгипетську пустелею серед земель спустошених; і міста її серед опустілих міст будуть порожніми сорок років, і розсію єгиптян серед народів, і розвію їх по землях.","Бо так говорить Господь Бог: після закінчення сорока років Я зберу єгиптян з народів, між якими вони будуть розсіяні;","і поверну полон Єгипту, і назад приведу їх у землю Пафрос, у землю походження їх, і там вони будуть царством слабким.","Воно буде слабкішим за інші царства, і не буде більш підноситися над народами; Я принижу їх, щоб вони не панували над народами.","І не будуть надалі дому Ізраїлевому опорою, що нагадує беззаконня їх, коли вони зверталися до нього; і пізнають, що Я Господь Бог.","У двадцять сьомому році, у першому місяці, у перший день місяця, було до мене слово Господнє:","сину людський! Навуходоносор, цар Вавилонський, стомив своє військо великими роботами біля Тира; усі голови оплішивіли й усі плечі стерті; а ні йому, ні війську його немає винагороди від Тира за роботи, які він зробив проти нього.","Тому так говорить Господь Бог: ось, Я Навуходоносору, царю Вавилонському, даю землю Єгипетську, щоб він обібрав багатство її і вчинив грабунок у ній, і пограбував награбоване нею, і це буде винагородою війську його.","У нагороду за справу, яку він зробив у ньому, Я віддаю йому землю Єгипетську, тому що вони робили це для Мене, — сказав Господь Бог.","У той день піднесу ріг дому Ізраїлевому, і тобі відкрию вуста серед них, і пізнають, що Я Господь."],"x":{"2":"31.19.1|32.46.2","3":"25.73.13|31.27.1","4":"25.31.9|31.37.29|36.38.4","5":"32.7.33|32.16.4|36.32.4","6":"11.18.21|31.36.6","8":"32.44.30","10":"36.30.6","11":"36.32.13","12":"36.30.23","13":"31.19.18","14":"0.10.14|32.44.1","16":"33.4.17|36.26.6","18":"25.136.8","20":"31.10.5","21":"36.24.27"}},{"v":["І було до мене слово Господнє:","сину людський! проречи пророцтво і скажи: так говорить Господь Бог: ридайте! о, злощасний день!","Бо близько день, так! близький день Господа, день похмурий; час народів настає.","І піде меч на Єгипет, і жах пошириться в Ефіопії, коли в Єгипті будуть падати уражені, коли візьмуть багатство його, й основи його будуть зруйновані;","Ефіопія і Лівія, і Лідія, і весь змішаний народ, і Хуб, і сини землі завіту разом з ними впадуть від меча.","Так говорить Господь: впадуть основи Єгипту, і впаде гординя могутности його; від Мигдола до Сиєни будуть падати у ньому від меча, — сказав Господь Бог.","І спустіє він серед спустошених земель, і міста його будуть серед спустошених міст.","І пізнають, що Я Господь, коли пошлю вогонь на Єгипет, і всі підпори його будуть розтрощені.","У той день підуть від Мене вісники на кораблях, щоб устрашити безтурботних ефіоплян, і пошириться у них жах, як у день Єгипту; тому що ось, він іде.","Так говорить Господь Бог: покладу кінець багатолюдності Єгипту рукою Навуходоносора, царя Вавилонського.","Він і з ним народ його, найлютіший з народів, приведені будуть на погибель цієї землі, і виймуть мечі свої на Єгипет, і наповнять землю ураженими.","І ріки зроблю сушею і віддам землю у руки злим, і рукою іноземців спустошу землю і все, що наповнює її. Я, Господь, сказав це.","Так говорить Господь Бог: знищу ідолів і знищу лжебогів у Мемфисі, і з землі Єгипетської не буде уже володаря, і наведу страх на землю Єгипетську.","І спустошу Пафрос і пошлю вогонь на Цоан, і вчиню суд над Но.","І виллю лють Мою на Син, фортецю Єгипту, і знищу багатолюдність у Но.","І пошлю вогонь на Єгипет; затремтить Син, і Но впаде, і на Мемфис нападуть вороги серед дня.","Молоді люди Она і Бубаста впадуть від меча, а інші підуть у полон.","І в Тафнисі померкне день, коли Я скрушу там ярмо Єгипту, і припиниться у ньому горда могутність його. Хмара закриє його, і дочки його підуть у полон.","Так учиню Я суд над Єгиптом, і пізнають, що Я Господь.","В одинадцятому році, у першому місяці, у сьомий день місяця, було до мене слово Господнє:","сину людський! Я вже скрушив м’язи фараону, царю Єгипетському; і ось, вони ще не обв’язані для лікування їх і не оповиті лікувальними перев’язками, від яких вони одержали б силу тримати меч.","Тому так говорить Господь Бог: ось, Я — на фараона, царя Єгипетського, і скрушу м’язи його, здорові і переламані, так що меч випаде з руки його.","І розсію єгиптян серед народів, і розвію їх по землях.","А м’язи царя Вавилонського зроблю міцними і дам йому меч Мій у руку, м’язи ж фараона скрушу, і він зранений буде сильно стогнати перед ним.","Зміцню м’язи царя Вавилонського, а м’язи у фараона опустяться; і пізнають, що Я Господь, коли меч Мій дам у руки царя Вавилонського, і він простягне його на землю Єгипетську.","І розсію єгиптян серед народів, і розвію їх по землях, і пізнають, що Я Господь."],"x":{"3":"39.2.2|46.1.14","4":"31.20.3","6":"36.29.10","8":"36.29.16","9":"1.12.29","11":"36.31.11","12":"31.19.5|36.5.17","13":"48.13.2","14":"32.44.1","15":"32.46.25|38.9.6","17":"1.1.11","18":"32.46.14","19":"32.1.16","21":"32.48.25","23":"36.29.12"}},{"v":["В одинадцятому році, у третьому місяці, у перший день місяця, було до мене слово Господнє:","сину людський! скажи фараонові, царю Єгипетському, і народу його: з ким ти зрівнюєш себе у величі твоїй?","Ось, Ассур був кедр на Ливані, з красивими гілками і тінистим листям, і високий на зріст; вершина його знаходилася серед товстих сучків.","Води вирощували його, безодня піднімала його, ріки її оточували розплідник його, і вона протоки свої посилала до усіх дерев польових.","Від того висота його перевищила усі дерева польові, і сучків на ньому було багато, і гілки його примножувалися, і сучки його ставали довгими від багатства вод, коли він розростався.","На сучках його вили гнізда всякі птахи небесні, під гілками його виводили дітей усякі звірі польові, і під тінню його жили всякі численні народи.","Він красувався висотою зросту свого, довжиною гілок своїх, бо корінь його був біля великих вод.","Кедри в саду Божому не затемнювали його; кипариси не рівнялися сучкам його, і каштани не були розміром як гілки його, жодне дерево у саду Божому не рівнялося з ним красою своєю.","Я прикрасив його безліччю гілок його, так що всі дерева едемські у саду Божому заздрили йому.","Тому так сказав Господь Бог: за те, що ти став високий на зріст і вершину свою виставив серед товстих сучків, і серце його загордилося величчю його, —","за те Я віддав його у руки володареві народів; він учинив з ним, як потрібно; за беззаконня його Я відкинув його.","І зрубали його чужоземці, найлютіші з народів, і повалили його на гори; і на всі долини упали гілки його; і сучки його скрушилися на всіх лощинах землі, і з-під тіні його відійшли всі народи землі, і залишили його.","На уламках його розмістилися всякі птахи небесні, і в сучках були всякі польові звірі.","Це для того, щоб ніякі дерева біля вод не величалися високим зростом своїм і не піднімали вершини свої із середини товстих сучків, і щоб не приліплялися до них через висоту їх дерева, що п’ють воду; бо усі вони будуть віддані на смерть, у пекельну країну разом із синами людськими, які відійшли у могилу.","Так говорить Господь Бог: у той день, коли він зійшов у могилу, Я засумував за ним, зачинив заради нього безодню і зупинив ріки її, і затримав великі води і потьмарив по ньому Ливан, і всі дерева польові були у тузі по ньому.","Шумом падіння його Я привів у трепет народи, коли звів його у пекло, до тих, що відійшли у могилу, і зраділи у пекельній країні усі дерева Едема, відмінні й найкращі ливанські, усі, що п’ють воду;","бо і вони з ним відійшли у пекло, до уражених мечем, і союзники його, які жили під тінню його, серед народів.","Отже, якому з дерев едемських дорівнював ти у славі і величі? Але тепер нарівні з деревами едемськими ти будеш зведений у пекло, будеш лежати серед необрізаних, з ураженими мечем. Це фараон і вся безліч народу його, — говорить Господь Бог."],"x":{"3":"36.32.22|25.36.35|37.4.7","5":"37.4.8","6":"37.4.9","8":"36.28.13","11":"36.30.11","12":"36.28.7|36.30.11","14":"25.33.17|25.62.10|25.142.7","15":"31.14.11","16":"31.14.9|36.28.8|36.32.18","18":"36.28.8"}},{"v":["У дванадцятому році, у дванадцятому місяці, у перший день місяця, було до мене слово Господнє:","сину людський! здійми плач за фараоном, царем Єгипетським, і скажи йому: ти як молодий лев між народами і як чудовисько у морях, кидаєшся у ріках твоїх, і каламутиш ногами твоїми води, і зневажаєш потоки їх.","Так говорить Господь Бог: Я закину на тебе сітку Мою у зібранні багатьох народів, і вони витягнуть тебе Моєю сіттю.","І викину тебе на землю, на відкритому полі кину тебе, і будуть сідати на тебе всякі небесні птахи, і будуть насичуватися тобою звірі всієї землі.","І розкидаю м’ясо твоє по горах, і долини наповню твоїми трупами.","І землю плавання твого напою кров’ю твоєю до самих гір; і рівчаки будуть наповнені тобою.","І коли ти згаснеш, закрию небеса і зірки їх потьмарю, сонце закрию хмарою, і місяць не буде світити світлом своїм.","Усі світила, що світяться на небі, затьмарю над тобою і на землю твою наведу пітьму, — говорить Господь Бог.","Приведу у збентеження серце багатьох народів, коли розголошу про падіння твоє між народами, по землях, яких ти не знав.","І наведу тобою жах на багато народів, і царі їх здригнуться за тебе у страху, коли мечем Моїм потрясу перед лицем їх, і щохвилинно будуть тремтіти кожен за душу свою у день падіння твого.","Бо так говорить Господь Бог: меч царя Вавилонського прийде на тебе.","Від мечів сильних упаде народ твій; усі вони — найлютіші з народів, і знищать гордість Єгипту, і загине вся безліч його.","І знищу всю худобу його біля великих вод, і надалі не буде каламутити їх нога людська, і копита худоби не будуть каламутити їх.","Тоді дам спокій водам їх, і зроблю, що ріки їх потечуть, як олія, — говорить Господь Бог.","Коли зроблю землю Єгипетську пустелею, і коли позбудеться земля усього, що наповнює її; коли уражу всіх, хто живе на ній, тоді пізнають, що Я Господь.","Ось жалібна пісня, яку будуть співати; дочки народів будуть співати її; про Єгипет і про всю безліч його будуть співати її, — говорить Господь Бог.","У дванадцятому році, у п’ятнадцятий день того самого місяця, було до мене слово Господнє:","сину людський! оплач народ єгипетський, і скинь його, його і дочок знаменитих народів у пекло, з тими, хто відходить у могилу.","Кого ти перевершуєш? зійди, і лежи з необрізаними.","Ті впадуть серед убитих мечем, і він відданий мечу; тягніть його і всю безліч його.","Серед пекла будуть говорити про нього і про союзників його перші з героїв; вони впали і лежать там між необрізаними, убиті мечем.","Там Ассур і все полчище його, навколо нього гроби їхні, всі уражені, полеглі від меча.","Гроби його поставлені у самій глибині пекла, і полчище його навколо гробниці його, всі уражені, полеглі від меча, ті, які поширювали жах на землі живих.","Там Елам із усією безліччю своєю навколо гробниці його, усі вони уражені, полеглі від меча, які необрізаними зійшли у пекло, які поширювали собою жах на землі живих і несуть ганьбу свою з тими, що відійшли у могилу.","Серед уражених дали ложе йому з усією безліччю його; навколо нього гроби їхні, всі необрізані, уражені мечем; і оскільки вони поширювали жах на землі живих, то і несуть на собі ганьбу нарівні з тими, що відійшли у могилу і покладені серед уражених.","Там Мешех і Фувал з усією безліччю своєю; навколо нього гроби їхні, всі необрізані, уражені мечем, тому що вони поширювали жах на землі живих.","Чи не повинні і вони лежати з полеглими героями необрізаними, які з військовою зброєю своєю зійшли у пекло і мечі свої поклали собі під голови, і залишилося беззаконня їхнє на кістках їхніх, тому що вони, як сильні, були жахом на землі живих.","І ти будеш скрушений серед необрізаних і лежатимеш з ураженими мечем.","Там Едом і царі його і всі князі його, які при всій своїй хоробрості покладені серед уражених мечем; вони лежать з необрізаними і тими, що зійшли у могилу.","Там володарі півночі, всі вони і всі сидоняни, які зійшли туди з ураженими, бувши посоромленими у могутності своїй, що наводила жах, і лежать вони з необрізаними, ураженими мечем, і несуть ганьбу свою з тими, що відійшли у могилу.","Побачить їх фараон і утішиться за всю безліч свою, вражену мечем, фараон і все військо його, — говорить Господь Бог.","Бо Я поширю страх Мій на землі живих, і покладений буде фараон і вся безліч його серед необрізаних з ураженими мечем, — говорить Господь Бог."],"x":{"2":"31.5.29|32.49.19|36.29.3","3":"36.12.13|36.17.20","4":"36.29.5","7":"31.13.10|39.2.31|39.3.15|50.24.29|51.13.24","9":"1.15.14","12":"36.28.7","13":"36.29.11","15":"36.30.8|36.33.29","18":"31.14.9|36.26.20|36.28.8","19":"31.14.11","21":"31.14.10","22":"36.31.3","23":"31.14.15","24":"0.10.22|32.49.34","25":"36.32.18"}},{"v":["І було до мене слово Господнє:","сину людський! виречи слово до синів народу твого і скажи їм: якщо Я на яку-небудь землю наведу меч, і народ тієї землі візьме із середовища свого людину і поставить її у себе стражем;","і вона, побачивши меч, який іде на землю, засурмить у трубу і застереже народ;","і якщо хто буде слухати голос труби, але не остереже себе, — то, коли меч прийде і захопить його, кров його буде на його голові.","Голос труби він чув, але не остеріг себе, кров його на ньому буде; а хто остерігся, той спас життя своє.","Якщо ж страж бачив меч, який іде, і не засурмив у трубу, і народ не був застережений, — то, коли прийде меч і візьме у когось із них життя, цей схоплений буде за гріх свій, але кров його стягну від руки стража.","І тебе, сину людський, Я поставив стражем дому Ізраїлевого, і ти будеш чути з уст Моїх слово і напоумляти їх від Мене.","Коли Я скажу беззаконникові: «беззаконнику! ти смертю помреш», а ти не будеш нічого говорити, щоб застерегти беззаконника від путі його, — то беззаконник той помре за гріх свій, але кров його стягну від руки твоєї.","Якщо ж ти застерігав беззаконника від путі його, щоб він навернувся від нього, але він від путі свого не навернувся, — то він помирає за гріх свій, а ти спас душу твою.","І ти, сину людський, скажи дому Ізраїлевому: ви говорите так: «злочини наші і гріхи наші на нас, і ми танемо у них: як же можемо ми жити?»","Скажи їм: живу Я, — говорить Господь Бог: не хочу смерти грішника, але щоб грішник навернувся від путі свого і живий був. Наверніться, наверніться від злих путів ваших; для чого помирати вам, доме Ізраїлів?","І ти, сину людський, скажи синам народу твого: праведність праведника не спасе у день злочину його, і беззаконник за беззаконня своє не упаде у день навернення від беззаконня свого, так само як і праведник у день гріха свого не може залишитися у живих за свою праведність.","Коли Я скажу праведнику, що він буде живий, а він понадіється на свою праведність і зробить неправду, — то всі праведні діла його не пом’януться, і він помре від неправди своєї, яку вчинив.","А коли скажу беззаконникові: «ти смертю помреш», і він навернеться від гріхів своїх і буде творити суд і правду,","якщо цей беззаконник поверне заставу, за вкрадене заплатить, буде ходити за законами життя, не роблячи нічого поганого, — то він буде живий, не помре.","Жоден із гріхів його, які він учинив, не пом’янеться йому; він став творити суд і правду, він буде живий.","А сини народу твого говорять: «неправий путь Господа», тоді як їх путь неправий.","Коли праведник відступив від праведности своєї і почав чинити беззаконня, — то він помре за те.","І коли беззаконник навернувся від беззаконня свого і став творити суд і правду, він буде за те живий.","А ви говорите: «неправий путь Господа!» Я буду судити вас, доме Ізраїлів, кожного за путями його.","У дванадцятому році нашого переселення, у десятому місяці, у п’ятий день місяця, прийшов до мене один із тих, хто врятувався з Єрусалима, і сказав: «зруйновано місто!»","Але ще до приходу цього, який урятувався, ввечері була на мені рука Господа, і Він відкрив мені вуста, перше ніж той прийшов до мене зранку. І відкрилися вуста мої, і я вже не був безмовний.","І було до мене слово Господнє:","сину людський! ті, що живуть на опустілих місцях у землі Ізраїлевій, говорять: «Авраам був один, і одержав у володіння землю цю, а нас багато; отже, нам дана земля ця у володіння».","Тому скажи їм: так говорить Господь Бог: ви їсте з кров’ю і зводите очі ваші до ідолів ваших, і проливаєте кров; і хочете володіти землею?","Ви спираєтеся на меч ваш, робите мерзоти, оскверняєте один дружину іншого, і хочете володіти землею?","Ось що скажи їм: так говорить Господь Бог: живу Я! ті, які на місцях розорених, упадуть від меча; а хто у полі, того віддам звірам на поживу; а які в укріпленнях і печерах, ті помруть від моровиці.","І зроблю землю пустелею з пустель, і горда могутність її припиниться, і гори Ізраїлеві спорожніють, так що не буде перехожих.","І пізнають, що Я Господь, коли зроблю землю пустелею з пустель за всі мерзоти їх, які вони робили.","А про тебе, сину людський, сини народу твого розмовляють біля стін і у дверях домів і говорять один одному, брат братові: «підіть і послухайте, яке слово вийшло від Господа».","І вони приходять до тебе, як на народне зборище, і сідає перед лицем твоїм народ Мій, і слухають слова твої, але не виконують їх; бо вони в устах своїх роблять з цього забаву, серце їхнє захоплюється користю їх.","І ось, ти для них — як забавний співак із приємним голосом і який добре грає; вони слухають слова твої, але не виконують їх.","Але коли збудеться, — ось, вже і збувається, — тоді пізнають, що серед них був пророк."],"x":{"2":"11.9.17","7":"31.58.1|36.3.17","8":"36.24.8|54.18.6","10":"25.37.5|25.89.8-9","11":"9.14.14|36.18.23:32|47.1.5","12":"36.18.24","13":"63.10.12","15":"1.22.26|4.24.13","16":"31.43.25|32.31.34","17":"36.18.25","20":"25.61.13|26.24.12|36.18.30|50.16.27|62.2.6","21":"11.25.4","22":"36.24.27","24":"62.4.13|31.51.2","25":"4.12.23","26":"36.22.11","27":"40.9.3","29":"36.26.6|36.28.24","31":"31.42.20|31.53.1"}},{"v":["І було до мене слово Господнє:","сину людський! виречи пророцтво на пастирів Ізраїлевих, виречи пророцтво і скажи їм, пастирям: так говорить Господь Бог: горе пастирям Ізраїлевим, які пасли себе самих! чи не стадо повинні пасти пастирі?","Ви їли жир і вовною одягалися, відгодованих овець заколювали, а стада не пасли.","Слабких не зміцнювали, і хворої вівці не лікували, і пораненої не перев’язували, і вкраденої не повертали, і загубленої не шукали, а правили ними з насильством і жорстокістю.","І розсіялися вони без пастиря і, розсіявшись, зробилися поживою всякому звіру польовому.","Блукають вівці Мої по всіх горах і по усякому високому пагорбі, і по всьому лиці землі розсіялися вівці Мої, і ніхто не розвідує про них, і ніхто не шукає їх.","Тому, пастирі, вислухайте слово Господнє.","Живу Я! — говорить Господь Бог; за те, що вівці Мої залишені були на розкрадання і без пастиря зробилися вівці Мої поживою всякого звіра польового, і пастирі Мої не шукали овець Моїх, і пасли пастирі самих себе, а овець Моїх не пасли, —","за те, пастирі, вислухайте слово Господнє.","Так говорить Господь Бог: ось, Я — на пастирів, і стягну овець Моїх від руки їх, і не дам їм більше пасти овець, і не будуть більше пастирі пасти самих себе, і вивергну овець Моїх із щелеп їхніх, і не будуть вони їжею їх.","Бо так говорить Господь Бог: ось, Я Сам знайду овець Моїх і огляну їх.","Як пастух перевіряє стадо своє у той день, коли знаходиться серед стада свого розсіяного, так Я перегляну овець Моїх і визволю їх із усіх місць, в яких вони були розсіяні у день хмарний і похмурий.","І виведу їх з народів, і зберу їх із країн, і приведу їх у землю їх, і буду пасти їх на горах Ізраїлевих, біля потоків і на всіх населених місцях землі цієї.","Буду пасти їх на доброму пасовищі, і загін їх буде на високих горах Ізраїлевих; там вони будуть відпочивати у доброму загоні і будуть пастися на рясному пасовищі, на горах Ізраїлевих.","Я буду пасти овець Моїх і Я буду заспокоювати їх, — говорить Господь Бог.","Загублену розшукаю і вкрадену поверну, і поранену перев’яжу, і хвору зміцню, а розжирілу і буйну знищу; буду пасти їх за правдою.","Вас же, вівці Мої, — так говорить Господь Бог, — ось, Я буду судити між вівцею і вівцею, між бараном і козлом.","Хіба мало вам того, що пасетеся на доброму пасовищі, а тим часом решту на пасовищі вашому топчете ногами вашими, п’єте чисту воду, а решту каламутите ногами вашими,","так що вівці Мої повинні годуватися тим, що потоптане ногами вашими, і пити те, що скаламучене ногами вашими?","Тому так говорить їм Господь Бог: ось, Я Сам буду судити між вівцею повною й вівцею худою.","Оскільки ви штовхаєте боком і плечем, і рогами своїми б’єте всіх слабких, доки не виштовхнете їх геть, —","то Я спасу овець Моїх, і їх не будуть уже розкрадати, і буду судити між вівцею і вівцею.","І поставлю над ними одного пастиря, який буде пасти їх, раба Мого Давида; він буде пасти їх і він буде у них пастирем.","І Я, Господь, буду їхнім Богом, і раб Мій Давид буде князем серед них. Я, Господь, сказав це.","І укладу з ними завіт миру і прожену з землі лютих звірів, так що безпечно будуть жити у степу і спати у лісах.","Дарую їм і околицям пагорба Мого благословення, і дощ буду посилати у свій час; це будуть дощі благословення.","І польове дерево буде давати плід свій, і земля буде давати плоди свої; і будуть вони безпечні на землі своїй, і пізнають, що Я Господь, коли скрушу зв’язки ярма їх і визволю їх від руки поневолювачів їх.","Вони не будуть вже здобиччю для народів, і польові звірі не будуть пожирати їх; вони будуть жити безпечно, і ніхто не буде страшити їх.","І вирощу у них насадження славне, і не будуть уже гинути від голоду на землі і терпіти посоромлення від народів.","І пізнають, що Я, Господь Бог їх, з ними, і вони, дім Ізраїлів, Мій народ, — говорить Господь Бог,","і що ви — вівці Мої, вівці пастви Моєї; ви — люди, а Я Бог ваш, — говорить Господь Бог."],"x":{"3":"32.23.1|48.11.17","4":"56.5.3","5":"31.53.6|50.9.36","10":"36.3.18|36.33.8","11":"48.13.7|53.10.12","12":"32.23.4|52.15.4","13":"46.3.13|25.64.14","14":"25.22.2","16":"50.10.6|50.15.24|52.15.4","17":"50.25.32","23":"25.22.1|31.40.11|32.23.5|36.37.24|53.10.11|75.13.20","25":"36.37.26|38.2.18","26":"39.2.23","27":"25.67.10","28":"32.46.27","29":"31.4.2|31.11.1","31":"25.99.3|36.36.37|53.10.11"}},{"v":["І було до мене слово Господнє:","сину людський! поверни лице твоє до гори Сеїр і проречи на неї пророцтво","і скажи їй: так говорить Господь Бог: ось, Я — на тебе, горо Сеїр! і простягну на тебе руку Мою і зроблю тебе порожньою і безлюдною.","Міста твої перетворю на руїни, і ти сама спустієш і пізнаєш, що Я Господь.","Оскільки у тебе вічна ворожнеча, і ти віддавала синів Ізраїлевих до рук меча під час нещастя їх, під час остаточної загибелі:","за це — живу Я! — говорить Господь Бог, — зроблю тебе кров’ю, і кров буде переслідувати тебе; оскільки ти не ненавиділа крови, то кров і буде переслідувати тебе.","І зроблю гору Сеїр порожнім і безлюдним степом і знищу на ній того, хто приходить, і того, хто повертається.","І наповню висоти її вбитими її; на пагорбах твоїх і в долинах твоїх, і в усіх рівчаках твоїх будуть падати убиті мечем.","Зроблю тебе пустелею вічною, і в містах твоїх не будуть жити, і пізнають, що Я Господь.","Оскільки ти говорила: ці два народи і ці дві землі будуть мої, і ми заволодіємо ними, хоч і Господь був там»:","за те, — живу Я! — говорить Господь Бог, — зроблю з тобою за мірою ненависти твоєї і заздрости твоєї, яку ти виявила з ненависти твоєї до них, і явлю Себе їм, коли буду судити тебе.","І пізнаєш, що Я, Господь, чув усі знущання твої, які ти промовляла на гори Ізраїлеві, говорячи: «спустіли! нам віддані на поживу!»","Ви величалися переді Мною язиком вашим і множили промови ваші проти Мене; Я чув це.","Так говорить Господь Бог: коли вся земля буде радіти, Я зроблю тебе пустелею.","Як ти раділа тому, що наділ дому Ізраїлевого спустів, так зроблю Я і з тобою: спустошена будеш, горо Сеїр, і вся Ідумея разом, і пізнають, що Я Господь."],"x":{"2":"36.25.8|41.1.10","3":"31.31.3","4":"36.7.27","5":"40.1.11|36.21.29","9":"49.1.4-5","10":"25.82.13","11":"36.7.27","12":"41.1.12","15":"41.1.15"}},{"v":["І ти, сину людський, виречи пророцтво на гори Ізраїлеві і скажи: гори Ізраїлеві! слухайте слово Господнє.","Так говорить Господь Бог: оскільки ворог говорить про вас: «а! а! і вічні висоти дісталися нам у наділ»,","то проречи пророцтво і скажи: так говорить Господь Бог: за те, саме за те, що спустошують вас і поглинають вас з усіх боків, щоб ви стали надбанням інших народів і піддалися лихослів’ю і пересудам людей, —","за це, гори Ізраїлеві, вислухайте слово Господа Бога: так говорить Господь Бог горам і пагорбам, лощинам і долинам, і спустілим руїнам, і залишеним містам, які зробилися здобиччю і посміянням іншим навколишнім народам;","за це так говорить Господь Бог: у вогні ревности Моєї Я вирік слово на інші народи і на всю Ідумею, які призначили землю Мою у володіння собі, з сердечною радістю і з презирством у душі прирікаючи її на здобич собі.","Тому проречи пророцтво про землю Ізраїлеву і скажи горам і пагорбам, лощинам і долинам: так говорить Господь Бог: ось, Я прорік це у ревності Моїй і у люті Моїй, тому що ви несете на собі посміяння від народів.","Тому так говорить Господь Бог: Я підняв руку Мою з клятвою, що народи, які навколо вас, самі понесуть сором свій.","А ви, гори Ізраїлеві, розпустіть гілля ваше і будете приносити плоди ваші народу Моєму Ізраїлю; бо вони скоро прийдуть.","Бо ось, Я до вас повернуся, і ви будете оброблені і засіяні.","І оселю на вас безліч людей, весь дім Ізраїлів, весь, і заселені будуть міста і забудовані руїни.","І примножу на вас людей і худобу, і вони будуть плодитися і розмножуватися, і заселю вас, як було у минулі часи ваші, і буду благодіяти вам більше, ніж за старих часів ваших, і пізнаєте, що Я Господь.","І приведу на вас людей, народ Мій, Ізраїля, і вони будуть володіти тобою, земле! і ти будеш спадщиною їх і не будеш більше робити їх бездітними.","Так говорить Господь Бог: за те, що говорять про вас: «ти — земля, що поїдає людей і робить народ твій бездітним»:","за те вже не будеш поїдати людей і народу твого не будеш надалі робити бездітним, — говорить Господь Бог.","І не будеш більше чути посміяння від народів, і наруги від племен не понесеш уже на собі, і народу твого надалі не будеш робити бездітним, — говорить Господь Бог.","І було до мене слово Господнє:","сину людський! коли дім Ізраїлів жив на землі своїй, він осквернював її поведінкою своєю і ділами своїми; путь їх перед лицем Моїм був як нечистота жінки під час очищення її.","І Я вилив на них гнів Мій за кров, яку вони проливали на цій землі, і за те, що вони осквернювали її ідолами своїми.","І Я розсіяв їх серед народів, і вони розвіяні по землях; Я судив їх за путями їх і за ділами їх.","І прийшли вони до народів, куди пішли, і знеславили святе ім’я Моє, тому що про них говорять: «вони — народ Господа, і вийшли з землі Його».","І пожалів Я святе ім’я Моє, яке знеславив дім Ізраїлів серед народів, куди прийшов.","Тому скажи дому Ізраїлевому: так говорить Господь Бог: не для вас Я зроблю це, доме Ізраїлів, а заради святого імені Мого, яке ви знеславили серед народів, куди прийшли.","І освячу велике ім’я Моє, знеславлене серед народів, серед яких ви знеславили його, і пізнають народи, що Я Господь, — говорить Господь Бог, — коли явлю на вас святість Мою перед очима їх.","І візьму вас з народів, і зберу вас з усіх країн, і приведу вас у землю вашу.","І окроплю вас чистою водою, і ви очиститеся від усіх скверн ваших, і від усіх ідолів ваших очищу вас.","І дам вам серце нове, і дух новий дам вам; і візьму з плоті вашої серце кам’яне, і дам вам серце плотське.","Вкладу всередину вас дух Мій і зроблю те, що ви будете ходити у заповідях Моїх і устави Мої будете дотримувати і виконувати.","І будете жити на землі, яку Я дав батькам вашим, і будете Моїм народом, і Я буду вашим Богом.","І звільню вас від усіх нечистот ваших, і призву хліб, і примножу його, і не дам вам терпіти голоду.","І примножу плоди на деревах і плоди полів, щоб надалі не терпіти вам ганьби від народів через голод.","Тоді згадаєте про злі путі ваші і недобрі діла ваші і відчуєте відразу до самих себе за беззаконня ваші і за мерзоти ваші.","Не заради вас Я зроблю це, — говорить Господь Бог, — нехай буде вам відомо. Червонійте і соромтеся шляхів ваших, доме Ізраїлів.","Так говорить Господь Бог: у той день, коли очищу вас від усіх беззаконь ваших і населю міста, і забудовані будуть руїни,","і спустошена земля буде оброблена, бувши пустелею в очах усякого, хто проходить мимо,","тоді скажуть: «ця опустіла земля зробилася, як сад Едемський; і ці розвалені й опустілі і розорені міста укріплені і населені».","І пізнають народи, які залишаться навколо вас, що Я, Господь, знову створюю зруйноване, засаджую спустіле. Я, Господь, сказав — і зробив.","Так говорить Господь Бог: ось, ще й у тім явлю милість Мою дому Ізраїлевому, примножу їх людьми як стадо.","Як багато буває жертовних овець у Єрусалимі під час свят його, так повні будуть людьми опустілі міста, і пізнають, що Я Господь."],"x":{"1":"36.6.2","2":"36.25.3|36.26.2|41.1.12","6":"36.39.25-26|39.2.18","8":"32.31.4-5","9":"48.8.12|48.10.8","11":"4.30.3:5","13":"2.26.38","15":"31.25.8","17":"31.64.6","19":"36.20.23|36.22.15","20":"31.52.5|62.2.24","21":"3.14.5-16","22":"4.9.6|36.36.32","23":"50.6.9|62.2.24|36.39.27","25":"31.44.3|48.13.1","26":"32.32.39|36.11.19|39.2.28|54.2.17","27":"31.59.21","28":"36.11.20|36.37.23","29":"25.31.2|38.2.21-22|48.9.17","31":"36.6.9|36.16.61","32":"36.36.22","35":"31.51.3","36":"36.17.24","38":"43.2.12"}},{"v":["Була на мені рука Господа, і Господь вивів мене духом і поставив мене серед поля, і воно було повне кісток,","і обвів мене навколо біля них, і ось дуже багато їх на поверхні поля, і ось вони дуже сухі.","І сказав мені: сину людський! чи оживуть кістки ці? Я сказав: Господи Боже! Ти знаєш це.","І сказав мені: проречи пророцтво на кістки ці і скажи їм: «кістки сухі! слухайте слово Господнє!»","Так говорить Господь Бог кісткам цим: ось, Я введу дух у вас, і оживете.","І обкладу вас жилами, і вирощу на вас плоть, і покрию вас шкірою, і введу у вас дух, і оживете, і пізнаєте, що Я Господь.","Я вирік пророцтво, як повелено було мені; і коли я пророкував, зчинився шум, і ось рух, і стали зближатися кістки, кістка з кісткою своєю.","І бачив я: і ось, жили були на них, і плоть виросла, і шкіра покрила їх зверху, а духу не було у них.","Тоді сказав Він мені: проречи пророцтво духу, проречи пророцтво, сину людський, і скажи духу: так говорить Господь Бог: від чотирьох вітрів прийди, ду́ше, і дихни на цих убитих, і вони оживуть.","І я вирік пророцтво, як Він повелів мені, і ввійшов у них дух, і вони ожили, і стали на ноги свої — дуже, дуже велике полчище.","І сказав Він мені: сину людський! кістки ці — весь дім Ізраїлів. Ось, вони говорять: «зсохли кістки наші, і загинула надія наша, ми відірвані від кореня».","Тому виречи пророцтво і скажи їм: так говорить Господь Бог: ось, Я відкрию гроби ваші і виведу вас, народ Мій, з гробів ваших і введу вас у землю Ізраїлеву.","І пізнаєте, що Я Господь, коли відкрию гроби ваші і виведу вас, народ Мій, із гробів ваших,","і вкладу у вас дух Мій, і оживете, і поміщу вас на землі вашій, і пізнаєте, що Я, Господь, сказав це — і зробив, — говорить Господь.","І було до мене слово Господнє:","ти ж, сину людський, візьми собі один жезл і напиши на ньому: «Іуді й синам Ізраїлевим, союзним з ним»; і ще візьми жезл і напиши на ньому: «Йосифу»: це жезл Єфрема і всього дому Ізраїлевого, союзного з ним.","І склади їх у себе один з одним в один жезл, щоб вони у руці твоїй були одне.","І коли запитають у тебе сини народу твого: «чи не поясниш нам, що це у тебе?»,","тоді скажи їм: так говорить Господь Бог: ось, Я візьму жезл Йосифів, який у руці Єфрема і союзних з ним колін Ізраїлевих, і прикладу їх до нього, до жезла Іуди, і зроблю їх одним жезлом, і будуть одне у руці Моїй.","Коли ж обидва жезли, на яких ти напишеш, будуть у руці твоїй перед очима їх,","то скажи їм: так говорить Господь Бог: ось, Я візьму синів Ізраїлевих із середовища народів, між якими вони знаходяться, і зберу їх звідусюди і приведу їх у землю їхню.","На цій землі, на горах Ізраїля Я зроблю їх одним народом, і один Цар буде царем у всіх них, і не будуть більше двома народами, і вже не будуть надалі розділятися на два царства.","І не будуть вже осквернювати себе ідолами своїми і мерзотами своїми і всякими пороками своїми, і звільню їх з усіх місць проживання їх, де вони грішили, і очищу їх, і будуть Моїм народом, і Я буду їхнім Богом.","А раб Мій Давид буде Царем над ними і Пастирем усіх їх, і вони будуть ходити за заповідями Моїми, і устави Мої будуть дотримувати і виконувати їх.","І будуть жити на землі, яку Я дав рабу Моєму Якову, на якій жили батьки їхні; там будуть жити вони і діти їхні, і діти дітей їхніх повіки; і раб Мій Давид буде князем у них вічно.","І укладу з ними завіт миру, завіт вічний буде з ними. І влаштую їх, і розмножу їх, і поставлю серед них святилище Моє навіки.","І буде у них оселя Моя, і буду їхнім Богом, а вони будуть Моїм народом.","І пізнають народи, що Я Господь, Який освячує Ізраїля, коли святилище Моє буде серед них повіки."],"x":{"1":"36.1.3","3":"31.26.19|37.12.2","4":"52.7.14|53.5.29","5":"0.2.7","8":"24.19.25-26","11":"33.4.8|53.11.39","14":"48.12.10|36.17.24","16":"36.4.1","21":"31.11.12","22":"53.10.16","23":"32.7.23","24":"31.40.11|32.23.5|32.30.9|36.34.23|53.10.11","25":"37.9.24","26":"25.88.4|36.34.25","27":"2.26.11-12|64.6.16|36.11.20"}},{"v":["І було до мене слово Господнє:","сину людський! поверни лице твоє до Гога у землі Магог, князя Роша, Мешеха і Фувала, і проречи на нього пророцтво","і скажи: так говорить Господь Бог: ось, Я — на тебе, Гог, князю Роша, Мешеха і Фувала!","І поверну тебе, і вкладу вудила у щелепи твої, і виведу тебе і все військо твоє, коней і вершників, усіх у повному озброєнні, велике полчище, у бронях і з щитами, усіх озброєних мечами,","персів, ефіоплян і лівійців з ними, всіх із щитами й у шоломах,","Гомера з усіма загонами його, дім Фогарма, від меж півночі, з усіма загонами його, багато народів з тобою.","Готуйся та знаряджайся, ти і всі полчища твої, що зібралися до тебе, і будь їм вождем.","Після багатьох днів ти знадобишся; в останні роки ти прийдеш у землю, врятовану від меча, зібрану з багатьох народів, на гори Ізраїлеві, які були у постійному запустінні, але тепер жителі її будуть повернуті з народів, і всі вони будуть жити безпечно.","І піднімешся, як буря, підеш, як хмара, щоб покрити землю, ти і всі полчища твої і багато народів з тобою.","Так говорить Господь Бог: у той день прийдуть тобі на серце думки, і ти задумаєш злий намір","і скажеш: «піднімуся я на землю необгороджену, піду на безтурботних, які живуть недбало, — усі вони живуть без стін, і немає у них ні запорів, ні дверей, —","щоб учинити грабіж і набрати здобичі, накласти руку на знову заселені руїни і на народ, зібраний з народів, що займається господарством і торгівлею, який живе на вершині землі».","Сава і Дедан і купці фарсиські з усіма молодими левами їх скажуть тобі: «ти прийшов, щоб учинити грабіж, зібрав полчище твоє, щоб набрати здобичі, взяти срібло і золото, відібрати худобу і майно, захопити велику здобич?»","Тому проречи пророцтво, сину людський, і скажи Гогу: так говорить Господь Бог: чи не так? у той день, коли народ Мій Ізраїль буде жити безпечно, ти пізнаєш це;","і підеш з місця твого, від меж півночі, ти і багато народів з тобою, всі, що сидять на конях, зборище велике і військо численне.","І піднімешся на народ Мій, на Ізраїля, як хмара, щоб покрити землю: це буде в останні дні, і Я приведу тебе на землю Мою, щоб народи пізнали Мене, коли Я над тобою, Гог, явлю святість Мою перед очима їх.","Так говорить Господь Бог: чи не ти той самий, про якого Я говорив у давні дні через рабів Моїх, пророків Ізраїлевих, які пророкували у ті часи, що Я приведу тебе на них?","І буде у той день, коли Гог прийде на землю Ізраїлеву, — говорить Господь Бог, — гнів Мій запалає у люті Моїй.","І в ревності Моїй, у вогні обурення Мого Я сказав: істинно у той день відбудеться велике потрясіння на землі Ізраїлевій.","І затремтять від імені Мого риби морські і птахи небесні, і звірі польові і всі плазуни, що повзають по землі, і всі люди, які на лиці землі, й обрушаться гори, і впадуть скелі, і всі стіни впадуть на землю.","І по всіх горах Моїх закличу меч проти нього, — говорить Господь Бог; меч кожної людини буде проти брата її.","І буду судитися з ним моровицею і кровопролиттям, і проллю на нього і на полки його і на багато народів, які з ним, всепотопляючий дощ і кам’яний град, вогонь і сірку;","і покажу Мою велич і святість Мою, і явлю Себе перед очима багатьох народів, і пізнають, що Я Господь."],"x":{"2":"76.20.7","3":"36.39.1","4":"11.19.28|36.29.4","6":"0.10.2-3","8":"31.24.22","16":"36.38.9","19":"50.24.29|52.21.26","20":"76.6.14","21":"51.13.12","22":"36.11.10|76.20.9","23":"36.26.6"}},{"v":["Ти ж, сину людський, проречи пророцтво на Гога і скажи: так говорить Господь Бог: ось, Я — на тебе, Гог, князь Роша, Мешеха і Фувала!","І поверну тебе, і поведу тебе, і виведу тебе від країв півночі, і приведу тебе на гори Ізраїлеві.","І виб’ю лук твій з лівої руки твоєї, і викину стріли твої з правої руки твоєї.","Упадеш ти на горах Ізраїлевих, ти й усі полки твої, і народи, які з тобою; віддам тебе на поживу всякого роду хижим птахам і звірам польовим.","На відкритому полі впадеш; бо Я сказав це, — говорить Господь Бог.","І пошлю вогонь на землю Магог і на жителів островів, які живуть безтурботно, і пізнають, що Я Господь.","І явлю святе ім’я Моє серед народу Мого, Ізраїля, і не дам надалі неславити святе ім’я Моє, і пізнають народи, що Я Господь, Святий в Ізраїлі.","Ось, це прийде і збудеться, — говорить Господь Бог, — це той день, про який Я сказав.","Тоді жителі міст Ізраїлевих вийдуть, і розпалять вогонь, і будуть спалювати зброю, щити і лати, луки і стріли, і булави і списи; сім років буду палити їх.","І не будуть носити дров з поля, ні рубати у лісах, але будуть палити тільки зброю; і пограбують грабіжників своїх, і обберуть оббирачів своїх, — говорить Господь Бог.","І буде у той день: дам Гогу місце для могили в Ізраїлі, долину перехожих на схід від моря, і вона буде затримувати перехожих; і поховають там Гога й усі полчища його, і будуть називати її долиною полчища Гогового.","І дім Ізраїлів сім місяців буде ховати їх, щоб очистити землю.","І весь народ землі буде ховати їх, і знаменитим буде у них день, в який Я прославлю Себе, — говорить Господь Бог.","І призначать людей, які постійно обходили б землю і за допомогою перехожих ховали б тих, що залишилися на поверхні землі, для очищення її; після семи місяців вони почнуть робити пошуки;","і коли хто з тих, що обходять землю, побачить кістку людську, то поставить біля неї знак, доки погребачі не поховають її у долині полчища Гогового.","І буде ім’я місту: Гамона [полчище]. І так очистять вони землю.","Ти ж, сину людський, — так говорить Господь Бог, — скажи всякого роду птахам і всім звірам польовим: збирайтеся і йдіть, з усіх боків сходьтеся до жертви Моєї, яку Я заколю для вас, до великої жертви на горах Ізраїлевих; і будете їсти м’ясо і пити кров.","М’ясо чоловіків сильних будете їсти, і будете пити кров князів землі, баранів, ягнят, козлів і тельців, усіх відгодованих на Васані;","і будете їсти жир до ситости і пити кров до сп’яніння від жертви Моєї, яку Я заколю для вас.","І насититеся за столом Моїм конями і вершниками, чоловіками сильними й усякими людьми військовими, — говорить Господь Бог.","І явлю славу Мою між народами, і всі народи побачать суд Мій, який Я звершу, і руку Мою, яку Я накладу на них.","І буде знати дім Ізраїлів, що Я Господь Бог їхній, від цього дня і далі.","І дізнаються народи, що дім Ізраїлів був переселений за неправду свою; за те, що вони чинили віроломно переді Мною, Я приховав від них лице Моє і віддав їх до рук ворогів їхніх, і всі вони впали від меча.","За нечистоти їхні і за їхнє беззаконня Я зробив це з ними, і приховав від них лице Моє.","Тому так говорить Господь Бог: нині поверну полон Якова, і помилую весь дім Ізраїля, і возревную за святе ім’я Моє.","І відчують вони нечестя своє і всі беззаконня свої, які чинили переді Мною, коли будуть жити на землі своїй безпечно, і ніхто не буде страшити їх,","коли Я поверну їх від народів, і зберу їх із земель ворогів їхніх, і явлю у них святість Мою перед очима багатьох народів.","І пізнають, що Я Господь Бог їхній, коли, розсіявши їх між народами, знову зберу їх у землю їхню і не залишу вже там жодного з них;","і не буду вже ховати від них лиця Мого, тому що Я виллю дух Мій на дім Ізраїлів, — говорить Господь Бог."],"x":{"1":"36.38.3","3":"38.2.18","4":"36.29.5|36.32.4","6":"76.20.7:9","7":"31.45.17|36.38.23","9":"31.9.5","17":"76.19.17|31.34.3","18":"31.34.6","21":"25.45.11","23":"32.50.7","25":"32.31.23|32.33.7|36.16.53","27":"32.32.37","29":"31.44.3|39.2.28|48.12.10"}},{"v":["У двадцять п’ятому році після переселення нашого, на початку року, у десятий день місяця, у чотирнадцятому році після зруйнування міста, у той самий день була на мені рука Господа, і Він повів мене туди.","У видіннях Божих привів Він мене у землю Ізраїлеву і поставив мене на дуже високій горі, і на ній, з південного боку, були ніби міські доми;","і привів мене туди. І ось муж, якого вигляд ніби вигляд блискучої міді, і лляний шнур у руці його і тростина для вимірювання, і стояв він біля воріт.","І сказав мені цей муж: «сину людський! дивись очима твоїми і слухай вухами твоїми, і прихили серце твоє до всього, що я буду показувати тобі, тому що ти для того і приведений сюди, щоб я показав тобі це; все, що побачиш, сповісти дому Ізраїлевому».","І ось, поза храмом стіна з усіх боків його, і у руці того мужа тростина для вимірювання у шість ліктів, рахуючи кожен лікоть у лікоть з долонею; і наміряв він у цьому домі одну тростину товщини й одну тростину висоти.","Потім пішов до воріт, обернених лицем на схід, і зійшов по східцях їх, і знайшов міри в одному порозі воріт одну тростину ширини і в другому порозі одну тростину ширини.","І в кожній бічній кімнаті одна тростина довжини й одна тростина ширини, а між кімнатами п’ять ліктів, і у порозі воріт у притворі воріт всередині одна ж тростина.","І зміряв він у притворі воріт усередині одну тростину,","а в притворі біля воріт наміряв вісім ліктів і два лікті у стовпах. Цей притвор біля воріт з боку храму.","Бічних кімнат біля східних воріт три — з одного боку і три — з іншого; одна міра у всіх трьох і одна міра у стовпах з того й іншого боку.","Ширини в отворі воріт він наміряв десять ліктів, а довжини воріт тринадцять ліктів.","А перед кімнатами виступ в один лікоть, і в один же лікоть з іншого боку виступ; ці кімнати з одного боку мали шість ліктів і шість же ліктів з іншого боку.","Потім наміряв він у воротах від даху однієї кімнати до даху іншої двадцять п’ять ліктів ширини; двері були навпроти дверей.","А у стовпах він налічив шістдесят ліктів, у кожнім стовпі біля двору і біля воріт,","і від передньої сторони входу у ворота до передньої сторони внутрішніх воріт п’ятдесят ліктів.","Ґратчасті вікна були й у бокових кімнатах і у стовпах їх, усередину воріт навколо, також і у притворах вікна були навколо на внутрішній бік, і на стовпах — пальми.","І привів він мене на зовнішній двір, і ось там кімнати, і кам’яний поміст навколо двору був зроблений; тридцять кімнат на тому помості.","І поміст цей був з боків воріт, відповідно до довжини воріт; цей поміст був нижче.","І наміряв він у ширину від нижніх воріт до зовнішнього краю внутрішнього двору сто ліктів, на схід і на північ.","Він виміряв також довжину і ширину воріт зовнішнього двору, повернених лицем на північ,","і бокові кімнати при них, три з одного боку і три з іншого; і стовпи їх, і виступи їх були такої самої міри, як у попередніх воріт: довжина їх п’ятдесят ліктів, а ширина двадцять п’ять ліктів.","І вікна їх, і виступи їх, і пальми їх — тієї ж міри, як у воріт, обернених лицем на схід; і входять до них сімома сходинками, і перед ними виступи.","І у внутрішній двір є ворота навпроти воріт північних і східних; і наміряв він від воріт до воріт сто ліктів.","І повів мене на південь, і ось там ворота південні; і наміряв він у стовпах і виступах таку саму міру.","І вікна у них і у переддвер’ях їх такі самі, як ті вікна: довжина п’ятдесят ліктів, а ширина двадцять п’ять ліктів.","Підйом до них — у сім сходинок, і переддвер’я перед ними; і пальмові прикраси — одна з того боку й одна з іншого на стовпах їх.","І у внутрішній двір були південні ворота; і наміряв він від воріт до воріт південних сто ліктів.","І привів він мене через південні ворота у внутрішній двір; і наміряв у південних воротах ту саму міру.","І бічні кімнати їх, і стовпи їх, і притвори їх — тієї самої міри, і вікна у них у притворах їх були навколо; усього в довжину п’ятдесят ліктів, а у ширину двадцять п’ять ліктів.","Притвори були навколо довжиною у двадцять п’ять ліктів, а шириною у п’ять ліктів.","І притвори були у них на зовнішній двір, і пальми були на стовпах їх; підйом до них — у вісім сходинок.","І повів мене східними воротами на внутрішній двір; і наміряв у цих воротах ту саму міру.","І бічні кімнати їх, і стовпи їх, і притвори їх були тієї самої міри; і вікна у них і притворах їх були навколо; довжина п’ятдесят ліктів, а ширина двадцять п’ять ліктів.","Притвори у них були на зовнішній двір, і пальми на стовпах їх з того й іншого боку; підйом до них — у вісім сходинок.","Потім привів мене до північних воріт, і наміряв у них ту саму міру.","Бічні кімнати при них, стовпи їх і притвори їх, і вікна у них були навколо; усього у довжину п’ятдесят ліктів, і у ширину двадцять п’ять ліктів.","Притвори у них були на зовнішній двір, і пальми на стовпах їх з того й іншого боку; підйом до них — у вісім сходинок.","Була також кімната, з входом до неї, біля стовпів воріт: там обмивають жертви всепалення.","А у притворі біля воріт два столи з одного боку і два з іншого боку, щоб заколювати на них жертви всепалення і жертви за гріх і жертви за злочин.","І біля зовнішнього боку біля входу в отвір північних воріт були два столи, і з іншого боку, поряд з притвором біля воріт, два столи.","Чотири столи з одного боку і чотири столи з іншого боку, з боків воріт: усього вісім столів, на яких заколюють жертви.","І чотири столи для приготування всепалення були з тесаних каменів, довжиною у півтора ліктя, і шириною у півтора ліктя, а висотою в один лікоть; на них кладуть знаряддя для заколення жертви всепалення та інших жертв.","І гаки в одну долоню прироблені були до стін будівлі навколо, а на столах клали жертовне м’ясо.","Ззовні внутрішніх воріт були кімнати для співців; на внутрішньому дворі, збоку північних воріт, одна обернена лицем на південь, а інша, збоку південних воріт, повернена лицем на північ.","І сказав він мені: «ця кімната, яка лицем до півдня, для священиків, що пильнують на сторожі храму;","а кімната, яка лицем на північ, для священиків, що пильнують на сторожі жертовника: це сини Садока, які одні із синів Левія наближаються до Господа, щоб служити Йому».","І наміряв він у дворі сто ліктів довжини і сто ліктів ширини: він був чотирикутний; а перед храмом стояв жертовник.","І привів він мене до притвору храму, і наміряв у стовпах притвору п’ять ліктів з одного боку і п’ять ліктів з іншого; а біля воріт три лікті ширини з одного боку і три лікті з іншого.","Довжина притвору — двадцять ліктів, а ширина — одинадцять ліктів, і сходять до нього по десяти сходинках; і були підпори у стовпів, одна з одного боку, а друга з іншого."],"x":{"1":"11.25.4|36.1.2-3","2":"76.21.10","3":"76.21.15|40.7.7|48.2.1","4":"36.43.10","5":"76.21.15:17","44":"12.23.5","46":"75.13.10","47":"36.43.13|1.40.5"}},{"v":["Потім увів мене до храму і наміряв у стовпах шість ліктів ширини з одного боку і шість ліктів ширини з іншого боку, на ширину скинії.","У дверях десять ліктів ширини, і з боків дверей п’ять ліктів з одного боку і п’ять ліктів з іншого боку; і наміряв довжини у храмі сорок ліктів, а ширини двадцять ліктів.","І пішов усередину, і наміряв у стовпах біля дверей два лікті й біля дверей шість ліктів, а ширина дверей — сім ліктів.","І відміряв у ньому двадцять ліктів у довжину і двадцять ліктів у ширину храму, і сказав мені: «це — Святе Святих».","І наміряв у стіні храму шість ліктів, а ширини у бічних кімнатах, навколо храму, по чотирі лікті.","Бічних кімнат було тридцять три, кімната біля кімнати; вони заходять у стіну, яка біля храму для кімнат навколо, так що вони пов’язані з нею, але стіни́ самого храму не торкаються.","І він більше і більше розширювався навколо вгору бічними кімнатами, тому що окружність храму піднімалася вище і вище навколо храму, і тому храм мав велику ширину вгорі, і з нижнього поверху піднімалися у верхній через середній.","І я бачив верх дому на усю окружність; бічні кімнати в основі мали там міри цілу тростину, шість повних ліктів.","Ширина стіни бічних кімнат, що виходять назовні, п’ять ліктів, і відкритий простір є біля бічних кімнат храму.","І між кімнатами відстань двадцять ліктів навколо всього храму.","Двері бічних кімнат ведуть на відкритий простір, одні двері — на північний бік, а інші двері — на південний бік; а ширина цього відкритого простору — п’ять ліктів навколо.","Будинок перед площею на західному боці — шириною у сімдесят ліктів; стіна ж цього будинку — п’ять ліктів ширини навколо, а довжина її — дев’яносто ліктів.","І наміряв він у храмі сто ліктів довжини, і у площі й у прибудові, й у стінах його також сто ліктів довжини.","І ширина храму з лицьового боку і площі на схід сто ж ліктів.","І у довжині будівлі перед площею на задньому боці її з бічними кімнатами її по той та інший бік він наміряв сто ліктів, з внутрішньою частиною храму і притворами двору.","Дверні бруси і ґратчасті вікна, і бічні кімнати навколо, в усіх трьох ярусах, навпроти порогів обшиті деревом і від підлоги до вікна; вікна були зачинені.","Від верху дверей як всередині храму, так і зовні, й по всій стіні навколо, всередині і зовні, були різьблені зображення,","зроблені були херувими і пальми: пальма між двома херувимами, й у кожного херувима два лиця.","З одного боку до пальми повернене лице людське, а з іншого боку до пальми — лице лев’яче; так зроблено в усьому храмі навколо.","Від підлоги до верху дверей зроблені були херувими і пальми, також і по стіні храму.","В храмі були чотирикутні одвірки, і святилище мало такий саме вигляд, як я бачив.","Жертовник був дерев’яний у три лікті висоти й у два лікті довжини; і кути його, і підніжжя його, і стінки його — з дерева. І сказав він мені: «це трапеза, яка перед Господом».","У храмі й у святилищі по двоє дверей,","і двері ці із двох дощок, обидві дошки рухомі, дві в одних дверях і дві дошки в інших;","і зроблені на них, на дверях храму, херувими і пальми такі самі, які зроблені по стінах; а перед притвором іззовні був дерев’яний поміст.","І ґратчасті вікна з пальмами, по той та інший бік, були з боків притвору й у бічних кімнатах храму і на дерев’яній обшивці."],"x":{"4":"1.26.33|2.16.2|36.43.12","7":"10.6.8","16":"10.6.4","18":"10.6.32|36.10.14","19":"36.1.10","22":"1.30.1-2","23":"10.6.34","26":"36.40.16"}},{"v":["І вивів мене до зовнішнього двору північною дорогою, і привів мене до кімнат, що навпроти площі й навпроти будівлі на півночі,","до того місця, що біля північних дверей має у довжину сто ліктів, а у ширину п’ятдесят ліктів.","Навпроти двадцяти ліктів внутрішнього двору і навпроти помосту, який на зовнішньому дворі, були галерея навпроти галереї у три яруси.","А перед кімнатами хід у десять ліктів ширини, а всередину в один лікоть; двері їх лицем на північ.","Верхні кімнати вужчі, тому що галереї віднімають у них трохи порівняно з нижніми і середніми кімнатами цієї будівлі.","Вони у три яруси, і таких стовпів, які на дворах, немає у них; тому вони і зроблені вужчими порівняно з нижніми і середніми кімнатами, починаючи від підлоги.","А зовнішня стіна навпроти цих кімнат від зовнішнього двору, що складає лицевий бік кімнат, має довжину п’ятдесят ліктів;","тому що і кімнати на зовнішньому дворі займають довжини тільки п’ятдесят ліктів, і ось перед храмом сто ліктів.","А знизу хід до цих кімнат зі східного боку, коли підходять до них із зовнішнього двору.","У ширину стіни двору на схід перед площею і перед будівлею були кімнати.","І хід перед ними такий самий, як і у тих кімнат, які обернені на північ, така сама довжина, як і у тих, і така сама ширина, і всі виходи їх, і будова їх, і двері їх такі самі, як і у тих.","Такі самі двері, як і у кімнатах, які на південь, і для входу у них двері біля самої дороги, яка йшла прямо уздовж стіни на схід.","І сказав він мені: «кімнати на північ і кімнати на південь, які перед площею, є кімнати священні, в яких священики, що наближаються до Господа, з’їдають найсвященніші жертви; там само вони кладуть найсвященніші жертви, і хлібні приношення, і жертву за гріх, і жертву за злочин, бо це місце святе.","Коли увійдуть туди священики, то вони не повинні виходити з цього святого місця на зовнішній двір, доки не залишать там одягу свого, в якому служили, бо вони священні; вони повинні одягнути на себе інший одяг і тоді виходити до народу».","Коли скінчив він вимірювання внутрішнього храму, то вивів мене воротами, оберненими лицем на схід, і став вимірювати його навколо.","Він виміряв східний бік вимірювальною тростиною і наміряв вимірювальною тростиною всього п’ятсот тростин;","на північному боці тією самою вимірювальною тростиною наміряв усього п’ятсот тростин;","на південній стороні наміряв вимірювальною тростиною також п’ятсот тростин.","Повернувши до західного боку, наміряв вимірювальною тростиною п’ятсот тростин.","Із усіх чотирьох боків він обміряв його; навколо нього була стіна довжиною у п’ятсот тростин і у п’ятсот тростин шириною, щоб відокремити святе місце від несвятого."],"x":{"1":"36.46.19","13":"2.10.17|31.64.11","14":"36.44.19","20":"36.45.2"}},{"v":["І привів мене до воріт, до тих воріт, що повернені лицем на схід.","І ось, слава Бога Ізраїлевого йшла від сходу, і глас Його — як шум вод великих, і земля освітилася від слави Його.","Це видіння було таке саме, яке я бачив раніше, точно таке, яке я бачив, коли приходив звістити загибель місту, і видіння, подібні до видінь, які бачив я біля ріки Ховари. І я впав на лице моє.","І слава Господа увійшла у храм шляхом воріт, обернених лицем до сходу.","І підняв мене дух, і увів мене у внутрішній двір, і ось, слава Господа наповнила весь храм.","І я чув когось, хто говорив до мене з храму, а той муж стояв біля мене,","і сказав мені: сину людський! це місце престолу Мого і місце стопам ніг Моїх, де Я буду жити серед синів Ізраїлевих повіки; і дім Ізраїлів не буде більше оскверняти святого імені Мого, ні вони, ні царі їхні, блудінням своїм і трупами царів своїх на висотах їх.","Вони ставили поріг свій біля порогу Мого і одвірки дверей своїх біля Моїх одвірків, так що одна стіна була між Мною і ними, й оскверняли святе ім’я Моє мерзотами своїми, які робили, і за те Я погубив їх у гніві Моєму.","А тепер вони відкинуть від Мене блудодіяння своє і трупи царів своїх, і Я буду жити серед них повіки.","Ти, сину людський, сповісти дому Ізраїлевому про храм цей, щоб вони посоромилися беззаконь своїх і щоб зняли з нього міру.","І якщо вони будуть соромитися всього того, що робили, то покажи їм вигляд храму і розташування його, і виходи його, і входи його, і всі обриси його, і всі устави його, і всі образи його, і всі закони його, і напиши на очах їхніх, щоб вони зберігали всі обриси його і всі устави його і жили за ними.","Ось закон храму: на вершині гори весь простір його навколо — Святе Святих; ось закон храму!","І ось розміри жертовника у ліктях, рахуючи лікоть за лікоть з долонею: основа у лікоть, ширина також у лікоть, і пояс по всіх краях його в одну п’ядь; і ось задній бік жертовника.","Від основи, що у землі, до нижнього виступу два лікті, а шириною він в один лікоть; від малого виступу до великого виступу чотири лікті, а ширина його — в один лікоть.","Сам жертовник висотою у чотири лікті; і з жертовника піднімаються вгору чотири роги.","Жертовник має дванадцять ліктів довжини і дванадцять ширини; він чотирикутний на усі свої чотири боки.","А в майданчику чотирнадцять ліктів довжини і чотирнадцять ширини на всі чотири боки його, і навколо нього пояс у півліктя, а основа його у лікоть навколо, сходи ж до нього зі сходу.","І сказав він мені: сину людський! так говорить Господь Бог: ось устави жертовника до того дня, коли він буде зроблений для приношення на ньому всепалень і для кроплення на нього кров’ю.","Священикам від коліна Левіїного, які з племені Садока, що наближаються до Мене, щоб служити Мені, — говорить Господь Бог, — дай тельця зі стада волів, у жертву за гріх.","І візьми крови його, і покропи на чотири роги його, і на чотирі кути майданчика, і на пояс навколо, і так очисти його й освяти його.","І візьми тельця, у жертву за гріх, і спали його на призначеному місці дому поза святилищем.","А на другий день у жертву за гріх принеси з козячого стада козла без пороку, і нехай очистять жертовник так само, як очищали тельцем.","Коли ж закінчиш очищення, приведи зі стада волів тельця без вад і з отари овець барана без вад;","і принеси їх перед лице Господа; і священики кинуть на них соли, і принесуть їх у всепалення Господу.","Сім днів принось у жертву за гріх по козлу в день; також нехай приносять у жертву по тельцю зі стада волів і по барану з отари овець без вад.","Сім днів вони повинні очищати жертовник і освячувати його і наповнювати руки свої.","Після закінчення ж цих днів, у восьмий день і далі, священики будуть підносити на жертовнику ваші всепалення і подячні жертви; і Я буду милостивий до вас, — говорить Господь Бог."],"x":{"1":"36.40.6","2":"36.1.24","3":"36.1.3","5":"36.8.3|1.40.34|10.8.11","7":"25.67.17|48.6.13|76.21.3","10":"36.16.63|36.40.4","12":"36.41.4","13":"36.40.5","17":"36.43.13","18":"1.40.16|2.8.11","19":"36.40.46","21":"2.16.3","26":"1.28.41"}},{"v":["І привів він мене назад до зовнішніх воріт святилища, повернених лицем на схід, і вони були зачинені.","І сказав мені Господь: ворота ці будуть зачинені, не відчиняться, і ніяка людина не ввійде ними, бо Господь, Бог Ізраїлів, увійшов ними, і вони будуть зачинені.","Що ж до князя, він, як князь, сяде у них, щоб їсти хліб перед Господом; увійде через притвор цих воріт, і тим самим шляхом вийде.","Потім привів мене шляхом воріт північних перед лице храму, і я бачив, і ось, слава Господа наповнювала дім Господа, й упав я на лице моє.","І сказав мені Господь: сину людський! прикладай серце твоє до всього, і дивися очима твоїми, і слухай вухами твоїми все, що Я говорю тобі про всі постанови дому Господа і всі закони його; і прихили серце твоє до входу у храм і до всіх виходів зі святилища.","І скажи бунтівному дому Ізраїлевому: так говорить Господь Бог: досить вам, доме Ізраїлів, робити всі мерзоти ваші,","вводити синів чужої, необрізаних серцем і необрізаних плоттю, щоб вони були в Моєму святилищі й оскверняли храм Мій, підносити хліб Мій, жир і кров, і руйнувати завіт Мій усякими мерзотами вашими.","Ви не виконували варти біля святинь Моїх, а ставили замість себе їх для сторо́жі у Моєму святилищі.","Так говорить Господь Бог: ніякий син чужої, необрізаний серцем і необрізаний плоттю, не повинен входити у святилище Моє, навіть і той син чужої, який живе серед синів Ізраїля.","Рівно ж і левити, які відійшли від Мене під час відступництва Ізраїля, які, залишивши Мене, блукали вслід ідолам своїм, понесуть покарання за провину свою.","Вони будуть служити біля святилища Мого, як вартові біля воріт храму і прислужники у храмі; вони будуть заколювати для народу всепалення й інші жертви, і будуть стояти перед ними для служіння їм.","За те, що вони служили їм перед ідолами їхніми і були для дому Ізраїлевого спокусою до нечестя, Я підняв на них руку Мою, — говорить Господь Бог, — і вони понесуть покарання за провину свою;","вони не будуть наближатися до Мене, щоб священнодіяти переді Мною і приступати до усіх святинь Моїх, до Святого Святих, але будуть нести на собі неславу свою і мерзоти свої, які чинили.","Зроблю їх вартовими храму для всіх служб його і для всього, що звершується у ньому.","А священики з коліна Левіїного, сини Садока, які, під час відступу синів Ізраїлевих від Мене, постійно стояли на сторо́жі святилища Мого, ті будуть наближатися до Мене, щоб служити Мені, і будуть стояти перед лицем Моїм, щоб приносити Мені жир і кров, — говорить Господь Бог.","Вони будуть входити у святилище Моє і наближатися до трапези Моєї, щоб служити Мені і нести варту Мою.","Коли прийдуть до воріт внутрішнього двору, тоді одягнуться в одежі лляні, а вовняне не повинне бути на них під час служіння їхнього біля воріт внутрішнього двору й усередині храму.","Завивала на головах їхніх повинні бути також лляні; і спідній одяг на стегнах їхніх повинен бути також лляним; у поту вони не повинні підперізуватися.","А коли потрібно буде вийти на зовнішній двір, на зовнішній двір до народу, тоді вони повинні будуть зняти одяг свій, в якому вони служили, і залишити його у священних кімнатах, і одягтися в інший одяг, щоб священним одягом своїм не доторкатися до народу.","І голови свої вони не повинні голити, і не повинні відпускати волосся, а нехай неодмінно стрижуть голови свої.","І вина не повинен пити жоден священик, коли йде у внутрішній двір.","Ні вдови, ні розведеної з чоловіком вони не повинні брати собі у дружини, а тільки можуть брати собі дівчат із племені дому Ізраїлевого і вдову, що залишилася вдовою від священика.","Вони повинні навчати народ Мій відрізняти священне від несвященного і пояснювати їм, що́ нечисте і що́ чисте.","При спірних справах вони повинні бути присутніми у суді, і за уставом Моїм судити їх, і зберігати закони Мої і постанови Мої про всі свята Мої, і свято зберігати суботи Мої.","До мертвої людини ніхто з них не повинен підходити, щоб не зробитися нечистим; тільки заради батька і матері, заради сина і дочки, брата і сестри, яка не була заміжньою, можна їм зробити себе нечистими.","Після очищення ж такого, ще сім днів слід відрахувати йому.","І в той день, коли йому потрібно буде приступати до святині у внутрішньому дворі, щоб служити при святині, він повинен принести жертву за гріх, — говорить Господь Бог.","А щодо наділу їхнього, то Я їхній наділ. І володіння не давайте їм у Ізраїлі: Я їхнє володіння.","Вони будуть їсти від хлібного приношення, від жертви за гріх і жертви за злочин; і все закляте у Ізраїлі їм же належить.","І початки з усіх плодів ваших і всякого роду приношення, з чого б не складалися приношення ваші, належать священикам; і початки меленого вами віддавайте священикові, щоб над домом твоїм спочивало благословення.","Ніякої мертвечини і нічого, роздертого звіром, ні з птахів, ні з худоби, не повинні їсти священики."],"x":{"1":"36.40.3","3":"36.46.8","4":"36.43.5","5":"36.40.4","6":"36.45.9|3.16.7","7":"54.21.28","10":"36.48.11|54.21.28","13":"38.4.6","15":"36.40.46|36.48.11","16":"2.24.6","17":"2.19.19|4.22.11","18":"1.28.42","19":"36.42.14","20":"2.19.27","21":"2.10.9","22":"2.21.13-14","23":"2.10.10|36.22.26|49.2.7","24":"4.17.18|13.19.10","25":"2.21.1","26":"3.19.11-2","28":"3.18.20|4.10.9|4.18.2","30":"1.13.2|1.22.29","31":"1.22.31|2.22.8"}},{"v":["Коли будете за жеребом ділити землю на наділи, тоді відокремте священну ділянку Господу у двадцять п’ять тисяч тростин довжини і десять тисяч ширини; нехай буде святе це місце в усьому обсязі своєму, навколо.","Від нього до святилища відійде чотирикутник по п’ятсот тростин навколо, і навколо нього площа у п’ятдесят ліктів.","З цієї міри відміряй двадцять п’ять тисяч тростин у довжину і десять тисяч у ширину, де буде знаходитися святилище, Святе Святих.","Ця священна частина землі буде належати священикам, служителям святилища, які приступають до служіння Господу: це буде для них місцем для домів і святинею для святилища.","Двадцять п’ять тисяч тростин довжини і десять тисяч ширини будуть належати левитам, служителям храму, як їхнє володіння для проживання їх.","І у володіння місту дайте п’ять тисяч ширини і двадцять п’ять тисяч довжини, навпроти священного місця, відділеного Господу; це має належати всьому дому Ізраїлевому.","І князеві дайте частку по той та інший бік, як біля священного місця, визначеного Господу, так і біля міського володіння, до заходу із західного боку і до сходу зі східного боку, довжиною нарівні з одним з тих наділів від західної межі до східної.","Це його земля, його володіння в Ізраїлі, щоб князі Мої надалі не тіснили народу Мого і щоб надали землю дому Ізраїлевому за колінами його.","Так говорить Господь Бог: досить вам, князі Ізраїлеві! відкладіть обра́зи і гноблення і чиніть суд і правду, перестаньте витісняти народ Мій із володіння його, — говорить Господь Бог.","Нехай будуть у вас правильні терези і правильна ефа і правильний бат.","Ефа і бат повинні бути однакової міри, так щоб бат вміщав у собі десяту частину хомера й ефа десяту частину хомера; міра їх повинна визначатися за хомером.","У сиклі двадцять гер; а двадцять сиклів, двадцять п’ять сиклів і п’ятнадцять сиклів будуть складати у вас мину.","Ось данина, яку ви повинні давати князеві: шосту частину ефи від хомера пшениці і шосту частину ефи від хомера ячменю;","постанова про єлей: від кора єлею десяту частину бата; десять батів складуть хомер, тому що у хомері десять батів;","одну вівцю від отари у двісті овець із багатого пасовища Ізраїля: усе це для хлібного приношення і всепалення, і подячної жертви, на очищення їх, — говорить Господь Бог.","Увесь народ землі зобов’язується робити це приношення князеві в Ізраїлі.","А на обов’язку князя будуть лежати всепалення і хлібне приношення, й узливання у свята й у новомісяччя, й у суботи, в усі торжества дому Ізраїлевого; він повинен буде приносити жертву за гріх і хлібне приношення, і всепалення, і жертву подячну для очищення дому Ізраїлевого.","Так говорить Господь Бог: у першому місяці, у перший день місяця, візьми зі стада волів тельця без вад, і очисти святилище.","Священик нехай візьме крови від цієї жертви за гріх і покропить нею на одвірки храму і на чотири кути майданчика біля жертовника і на одвірки воріт внутрішнього двору.","Те саме зроби й у сьомий день місяця за тих, хто грішить навмисно і за простотою, і так очищайте храм.","У першому місяці, у чотирнадцятий день місяця, повинна бути у вас Пасха, свято семиденне, коли слід їсти опрісноки.","У цей день князь за себе і за весь народ землі принесе тельця у жертву за гріх.","І в ці сім днів свята він повинен приносити у всепалення Господу щодня по сім тельців і по сім баранів без вад, і у жертву за гріх щодня по козлу з козячого стада.","Хлібного приношення він повинен приносити по ефі на тельця і по ефі на барана і по гину єлею на ефу.","В сьомому місяці, у п’ятнадцятий день місяця, у свято, протягом семи днів він повинен приносити те саме: таку саму жертву за гріх, таке саме всепалення, і стільки ж хлібного приношення і стільки ж єлею."],"x":{"1":"36.48.8-9","2":"36.42.20","8":"36.46.18","9":"36.44.6|31.1.16","10":"2.19.35","12":"1.30.13|2.27.25|3.3.47","17":"36.46.11-12","21":"2.23.5|3.28.16-17","22":"36.46.2","23":"3.28.24","24":"36.46.11","25":"3.29.12"}},{"v":["Так говорить Господь Бог: ворота внутрішнього двору, повернені лицем на схід, повинні бути замкнені протягом шести робочих днів, а у суботній день вони повинні бути відчинені й у день новомісяччя повинні бути відчинені.","Князь піде через зовнішній притвор воріт і стане біля одвірка цих воріт; і священики звершать його всепалення і його подячну жертву; і він біля порога воріт вклониться Господу, і вийде, а ворота залишаються незамкненими до вечора.","І народ землі буде поклонятися перед Господом, при вході у ворота, у суботи і новомісяччя.","Всепалення, яке князь принесе Господу в суботній день, повинно бути із шести агнців без вад та із барана без вад;","хлібного приношення ефа на барана, а на агнців хлібного приношення, скільки рука його подасть, а єлею гин на ефу.","В день новомісяччя будуть принесені ним зі стада волів телець без вад, також шість агнців і баран без вад.","Хлібного приношення він принесе ефу на тельця та ефу на барана, а на агнців, скільки рука його подасть, і єлею гин на ефу.","І коли буде приходити князь, то повинен входити через притвор воріт і тим самим шляхом виходити.","А коли народ землі буде приходити перед лице Господа у свята, то той, хто входить північними воротами для поклоніння, повинен виходити воротами південними, а той, хто входить південними воротами, повинен виходити воротами північними; він не повинен виходити тими самими воротами, якими увійшов, а повинен виходити протилежними.","І князь повинен знаходитися серед них; коли вони входять, входить і він; і коли вони виходять, виходить і він.","І у свята і в урочисті дні хлібного приношення від нього повинно бути по ефі на тельця і по ефі на барана, а на агнців, скільки подасть рука його, і єлею по гину на ефу.","А якщо князь, з ревности своєї, захоче принести всепалення або подячну жертву Господу, то повинні відчинити йому ворота, повернені на схід, і він звершить своє всепалення і свою подячну жертву так само, як звершив у суботній день, і після цього він вийде, і після виходу його ворота замкнуться.","Щодня принось Господу у всепалення однолітнього агнця без вад; щоранку принось його.","А хлібного приношення додавай до нього щоранку шосту частину ефи і єлею третю частину гина, щоб розчинити борошно; така вічна постанова про хлібне приношення Господу, назавжди.","Нехай приносять у всепалення агнця і хлібне приношення і єлей щоранку постійно.","Так говорить Господь Бог: якщо князь дає кому із синів своїх подарунок, то це має піти у спадщину і його синам; це володіння їхнє має бути спадкоємним.","Якщо ж він дасть зі спадщини своєї кому-небудь із рабів своїх подарунок, те це буде належати йому тільки до року звільнення, і тоді повернеться до князя. Тільки до синів його має переходити спадщина його.","Але князь не може брати зі спадкоємної ділянки народу, витісняючи їх із володіння їхнього; тільки зі свого володіння він може наділяти дітям своїм, щоб ніхто з народу Мого не був вигнаний зі свого володіння.","І привів він мене тим ходом, який збоку воріт, до священних кімнат для священиків, повернених на північ, і ось там одне місце на краю на захід.","І сказав мені: «це — місце, де священики повинні варити жертву за злочин і жертву за гріх, де повинні пекти хлібне приношення, не виносячи його на зовнішній двір, для освячення народу».","І вивів мене на зовнішній двір, і провів мене по чотирьох кутах двору, і ось, у кожнім куті двору ще двір.","У всіх чотирьох кутах двору були покриті двори у сорок ліктів довжини і тридцять ширини, однієї міри в усіх чотирьох кутах.","І навколо усіх їх чотирьох — стіни, а біля стін зроблені вогнища навколо.","І сказав мені: «ось куховарні, у яких служителі храму варять жертви народні»."],"x":{"2":"36.45.22","4":"3.28.10","8":"36.44.3","11":"3.28.26|36.45.17","13":"3.28.3","18":"36.45.8|10.21.3","19":"36.42.1","24":"8.2.13"}},{"v":["Потім привів він мене назад до дверей храму, і ось, з-під порога храму тече вода на схід, бо храм стояв лицем на схід, і вода текла з-під правого боку храму, з південного боку жертовника.","І вивів мене північними воротами, і зовнішнім шляхом обвів мене до зовнішніх воріт, шляхом, поверненим на схід; і ось, вода тече праворуч.","Коли той муж пішов на схід, то в руці тримав шнур, і відміряв тисячу ліктів, і повів мене по воді; води було по щиколотку.","І ще відміряв тисячу, і повів мене по воді; води було по коліно. І ще відміряв тисячу, і повів мене; води було по пояс.","І ще відміряв тисячу, і вже тут був такий потік, через який я не міг іти, тому що вода була така висока, що треба було пливти, а переходити не можна було цей потік.","І сказав мені: «бачив, сину людський?» і повів мене назад до берега цього потоку.","І коли я прийшов назад, і ось, на берегах потоку багато було дерев по той та інший бік.","І сказав мені: ця вода тече на східну сторону землі, зійде на рівнину і ввійде у море; і води його зробляться здоровими.","І всяка жива істота, яка плазує там, де ввійдуть два струмені, буде живою; і риби буде дуже багато, тому що ввійде туди ця вода, і во́ди у морі зробляться здоровими, і, куди ввійде цей потік, усе буде живе там.","І будуть стояти біля його рибалки від Ен-Гадді до Еглаїма, будуть закидати сіті. Риба буде у своєму вигляді і, як у великому морі, риби буде дуже багато.","Болота його і калюжі його, які не стануть здоровими, будуть залишені для соли.","Біля потоку по берегах його, з того й іншого боку, будуть рости всякі дерева, які приносять їжу: листя їх не будуть в’янути, і плоди на них не будуть виснажуватися; кожен місяць будуть визрівати нові, тому що вода для них тече зі святилища; плоди їх будуть уживані в їжу, а листя на лікування.","Так говорить Господь Бог: ось розподіл, за яким ви повинні розділити землю у спадщину дванадцятьом колінам Ізраїлевим: Йосифові два наділи.","І успадковуйте її, як один, так і другий; оскільки Я, піднявши руку Мою, клявся віддати її батькам вашим, то і буде земля ця спадщиною вашою.","І ось межа землі: на північному краю, починаючи від великого моря, через Хетлон, по дорозі у Цедад,","Емаф, Берот, Сивраїм, що знаходиться між Дамаською й Емафською областями Гацар-Тихон, який на кордоні Аврана.","І буде кордон від моря до Гацар-Енон, кордон з Дамаском, і далі на півночі область Емаф; і ось північний край.","Межу східного краю ведіть між Авраном і Дамаском, між Галаадом і землею Ізраїльською, по Йордану, від північного краю до східного моря; це східний край.","А південний край з полуденної сторони від Тамари до вод сперечання при Кадисі, і за течією потоку до великого моря; це полуденний край на півдні.","Західна ж межа — велике море, від південного кордону до місця навпроти Емафа; це західний край.","І розділіть собі землю цю на наділи за колінами Ізраїлевими.","І розділіть її за жеребом у спадщину собі й іноземцям, які живуть у вас, які народили у вас дітей; і вони серед синів Ізраїлевих повинні вважатися нарівні з природними жителями, і вони з вами ввійдуть у частку серед колін Ізраїлевих.","У якому коліні живе іноземець, у тому і дайте йому спадщину його, — говорить Господь Бог."],"x":{"1":"48.14.8","5":"62.11.33","7":"76.22.1-2","8":"48.14.8","9":"62.11.16|50.13.47","10":"32.16.16","12":"31.65.22|76.22.2","14":"0.12.7","17":"3.34.9","18":"3.34.10","19":"3.20.13|3.34.3|36.48.28","22":"31.56.3|65.3.28"}},{"v":["Ось імена колін. На північному краю по дорозі від Хетлона, що веде в Емаф, Гацар-Енон, від північного кордону Дамаска по шляху до Емафа: все це від сходу до моря один наділ Дану.","Поряд з межею Дана, від східного краю до західного, це один наділ Асиру.","Поряд з межею Асира, від східного краю до західного, це один наділ Неффалиму.","Поряд з межею Неффалима, від східного краю до західного, це один наділ Манассії.","Поряд з межею Манассії, від східного краю до західного, це один наділ Єфрему.","Поряд з межею Єфрема, від східного краю до західного, це один наділ Рувиму.","Поряд з межею Рувима, від східного краю до західного, це один наділ Іуді.","А поряд з межею Іуди, від східного краю до західного, священна ділянка, шириною у двадцять п’ять тисяч тростин, а довжиною нарівні з іншими наділами, від східного краю до західного; серед нього буде святилище.","Ділянка, яку ви присвятите Господу, довжиною буде у двадцять п’ять тисяч, а шириною у десять тисяч тростин.","І ця священна ділянка повинна належати священикам, на північ двадцять п’ять тисяч і до моря у ширину десять тисяч, і на схід у ширину десять тисяч, а на південь у довжину двадцять п’ять тисяч тростин, і серед неї буде святилище Господнє.","Це присвятите священикам із синів Садока, які стояли на варті Моїй, які під час відступництва синів Ізраїлевих не відступили від Мене, як відступили інші левити.","Їм буде належати ця частина землі зі священної ділянки, святиня зі святинь, біля межі левитів.","І левити одержать також біля межі священичої двадцять п’ять тисяч у довжину і десять тисяч тростин у ширину; уся довжина двадцять п’ять тисяч, а ширина десять тисяч тростин.","І з цієї частини вони не можуть ні продати, ні проміняти; і початки землі не можуть переходити до інших, тому що це святиня Господня.","А решту п’ять тисяч у ширину з двадцятьма п’ятьма тисячами у довжину призначаються для міста на загальне використання, на заселення і на передмістя; місто буде у середині.","І ось розміри його: північна сторона чотири тисячі п’ятсот і південна сторона чотири тисячі п’ятсот, східна сторона чотири тисячі п’ятсот і західна сторона чотири тисячі п’ятсот тростин.","А передмістя міста до півночі двісті п’ятдесят, і до сходу двісті п’ятдесят, і до півдня двісті п’ятдесят, і до заходу двісті п’ятдесят тростин.","А що залишається з довжини навпроти священної ділянки, десять тисяч на схід і десять тисяч на захід, навпроти священної ділянки, плоди з цієї землі повинні бути для споживи тих, що працюють у місті.","Працювати ж у місті можуть працівники з усіх колін Ізраїлевих.","Усю відділену ділянку у двадцять п’ять тисяч довжини й у двадцять п’ять тисяч ширини, чотирикутну, виділіть у священний наділ, із включенням володінь міста;","а решту князеві. Як з боку священної ділянки, так і з боку володінь міста, навпроти двадцяти п’яти тисяч тростин до східної межі ділянки, і на захід навпроти двадцяти п’яти тисяч біля західної межі співмірно з цими наділами, наділ князю, так що священна ділянка і святилище будуть всередині нього.","І те, що від володінь левитських і від володінь міста залишається у проміжку, належить також князю; проміжок між межою Іуди і між межою Веніаміна буде належати князю.","Решту ж від колін, від східного краю до західного — один наділ Веніаміну.","Поряд межі Веніаміна, від східного краю до західного — один наділ Симеону.","Поряд межі Симеона, від східного краю до західного — один наділ Іссахару.","Поряд межі Іссахара, від східного краю до західного — один наділ Завулону.","Поряд межі Завулона, від східного краю до західного — один наділ Гаду.","А поряд межі Гада на південній стороні йде південна межа від Тамари до вод сперечання при Кадисі, уздовж потоку до великого моря.","Ось земля, яку ви за жеребом розділите колінам Ізраїлевим, і ось ділянки їх, — говорить Господь Бог.","І ось виходи міста: з північної сторони міри чотири тисячі п’ятсот;","і ворота міста називаються іменами колін Ізраїлевих; на півночі троє воріт: ворота Рувимові одні, ворота Іудині одні, ворота Левіїні одні.","І зі східної сторони міри чотири тисячі п’ятсот, і троє воріт: ворота Йосифа одні, ворота Веніаміна одні, ворота Данові одні;","і з південної сторони міри чотири тисячі п’ятсот, і троє воріт: ворота Симеонові одні, ворота Іссахарові одні, ворота Завулонові одні.","З морської сторони міри чотири тисячі п’ятсот, воріт тут троє ж: ворота Гадові одні, ворота Асирові одні, ворота Неффалимові одні.","Усього навколо вісімнадцять тисяч. А ім’я місту з того дня буде: «Господь там»."],"x":{"8":"36.45.1","9":"36.45.1","11":"36.44.15","14":"2.25.34","20":"76.21.16","28":"36.47.19","31":"76.21.12","35":"31.62.2|2.26.12|25.45.6"}}];
export default C;
